INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (3, 'M03.17', 'Exam Question Bank', 17)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In what equipment is a photon radiated when an electron leaves a hole?', '[{"id": "a", "text": "Photo-cell.", "correct": false}, {"id": "b", "text": "LED.", "correct": true}, {"id": "c", "text": "Photo diode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The unit which consists of two or more different types of atoms is known as a', '[{"id": "a", "text": "particle of an element.", "correct": false}, {"id": "b", "text": "molecule of a compound.", "correct": true}, {"id": "c", "text": "molecule of an element.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A neutron has', '[{"id": "a", "text": "no electrical charge but will add weight to the nucleus.", "correct": true}, {"id": "b", "text": "the same charge as an Electron but half the mass.", "correct": false}, {"id": "c", "text": "the opposite charge to an Electron but half the weight of a proton.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The smallest particle that a substance can be split and show the same properties as the whole is known as', '[{"id": "a", "text": "an Element.", "correct": false}, {"id": "b", "text": "a Molecule.", "correct": false}, {"id": "c", "text": "an Atom.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What charge does the nucleus of an atom possess?', '[{"id": "a", "text": "Positive.", "correct": true}, {"id": "b", "text": "Neutral.", "correct": false}, {"id": "c", "text": "Negative.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the maximum number of electrons in shell N of an atom?', '[{"id": "a", "text": "18.", "correct": false}, {"id": "b", "text": "32.", "correct": true}, {"id": "c", "text": "16.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An oxygen molecule is made up of', '[{"id": "a", "text": "two oxygen atoms sharing neutrons.", "correct": false}, {"id": "b", "text": "two oxygen atoms sharing protons.", "correct": false}, {"id": "c", "text": "two oxygen atoms sharing electrons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If electrons are added to an atom it becomes', '[{"id": "a", "text": "a neutral ion.", "correct": false}, {"id": "b", "text": "a positive ion.", "correct": false}, {"id": "c", "text": "a negative ion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An element whose atoms have fewer than 4 electrons in their valency shell are', '[{"id": "a", "text": "semiconductors.", "correct": false}, {"id": "b", "text": "good insulators.", "correct": false}, {"id": "c", "text": "good conductors.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The charge on a proton is', '[{"id": "a", "text": "positive.", "correct": true}, {"id": "b", "text": "negative.", "correct": false}, {"id": "c", "text": "neutral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What effect do the electrons of one atom have upon the electrons of another atom?', '[{"id": "a", "text": "They have no effect on each other.", "correct": false}, {"id": "b", "text": "They repel each other.", "correct": true}, {"id": "c", "text": "They attract each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is a molecule?', '[{"id": "a", "text": "The smallest part of an atom.", "correct": false}, {"id": "b", "text": "The smallest part of a compound.", "correct": true}, {"id": "c", "text": "The smallest part of an electron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An atom is', '[{"id": "a", "text": "the smallest part of an element that retains its characteristics.", "correct": true}, {"id": "b", "text": "the smallest part of a compound that can exist independently.", "correct": false}, {"id": "c", "text": "the smallest particle of matter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A neutron is a particle which is', '[{"id": "a", "text": "is contained in the nucleus of all atoms.", "correct": false}, {"id": "b", "text": "orbits the nucleus of the atom.", "correct": false}, {"id": "c", "text": "is contained within the nucleus of most atoms.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The mass of an atom is contained mainly in the', '[{"id": "a", "text": "proton.", "correct": false}, {"id": "b", "text": "nucleus.", "correct": true}, {"id": "c", "text": "electron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When an atom loses or gains an electron it is called', '[{"id": "a", "text": "a molecule.", "correct": false}, {"id": "b", "text": "a current.", "correct": false}, {"id": "c", "text": "an ion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A good electrical insulator is a material which', '[{"id": "a", "text": "contains a large number of positive ions.", "correct": false}, {"id": "b", "text": "has its electrons tightly bound to their parent atoms.", "correct": true}, {"id": "c", "text": "has more protons than electrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An electric current is', '[{"id": "a", "text": "an ordered flow of electrons.", "correct": true}, {"id": "b", "text": "a surplus of free electron.", "correct": false}, {"id": "c", "text": "an excitement of electrons in a metal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An atom contains', '[{"id": "a", "text": "hydrogen.", "correct": false}, {"id": "b", "text": "molecules.", "correct": false}, {"id": "c", "text": "electrons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Germanium and silicon have how many electrons in their outer shell?', '[{"id": "a", "text": "6.", "correct": false}, {"id": "b", "text": "4.", "correct": true}, {"id": "c", "text": "2.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a free electron is given to another atom, that atom is a', '[{"id": "a", "text": "valency atom.", "correct": false}, {"id": "b", "text": "negative ion.", "correct": true}, {"id": "c", "text": "positive ion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The atomic number of an atom is determined by the number of', '[{"id": "a", "text": "protons.", "correct": true}, {"id": "b", "text": "electrons.", "correct": false}, {"id": "c", "text": "neutrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The valence electron is', '[{"id": "a", "text": "the electron in outer shell of atom.", "correct": true}, {"id": "b", "text": "the electron in inner shell of atom.", "correct": false}, {"id": "c", "text": "a positive electron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An atom with a deficiency in electrons has', '[{"id": "a", "text": "low resistance.", "correct": true}, {"id": "b", "text": "high resistance.", "correct": false}, {"id": "c", "text": "high impedance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An atom with less than 4 electrons in its outer shell has', '[{"id": "a", "text": "low electrical resistance.", "correct": true}, {"id": "b", "text": "no electrical resistance.", "correct": false}, {"id": "c", "text": "high electrical resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Elements such as phosphorus with 5 electrons in their outer shell, when combined with pure silicon, is a', '[{"id": "a", "text": "isotopic.", "correct": false}, {"id": "b", "text": "acceptor.", "correct": false}, {"id": "c", "text": "donor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An hydrogen atom consist of a', '[{"id": "a", "text": "Proton, Neutron and an Electron.", "correct": false}, {"id": "b", "text": "Proton and an Electron only.", "correct": true}, {"id": "c", "text": "Neutron and a proton only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'For an atom to become a negative ion it must', '[{"id": "a", "text": "gain at least one electron.", "correct": true}, {"id": "b", "text": "have undergone ionisation by the sun.", "correct": false}, {"id": "c", "text": "lose at least one electron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the maximum number of electrons in shell M of an atom?', '[{"id": "a", "text": "18.", "correct": true}, {"id": "b", "text": "6.", "correct": false}, {"id": "c", "text": "16.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A neutral atom with an atomic no. of 3 has how many electrons?', '[{"id": "a", "text": "1.", "correct": false}, {"id": "b", "text": "3.", "correct": true}, {"id": "c", "text": "Dependant on type of atom.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The nucleus of an atom is', '[{"id": "a", "text": "neutral.", "correct": false}, {"id": "b", "text": "positive charged.", "correct": true}, {"id": "c", "text": "negative charged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Electron orbits are called', '[{"id": "a", "text": "waves.", "correct": false}, {"id": "b", "text": "shells.", "correct": true}, {"id": "c", "text": "valences.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A neutral atom gains electrons', '[{"id": "a", "text": "It gains a positive charge.", "correct": false}, {"id": "b", "text": "It gains a negative charge.", "correct": true}, {"id": "c", "text": "It remains neutral.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An oxygen atom has', '[{"id": "a", "text": "protons and electrons.", "correct": false}, {"id": "b", "text": "neutrons and protons.", "correct": false}, {"id": "c", "text": "protons, neutrons and electrons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A semi-conductor will have', '[{"id": "a", "text": "two electrons in the outer shell.", "correct": false}, {"id": "b", "text": "four electrons in the outer shell.", "correct": true}, {"id": "c", "text": "eight electrons in the outer shell.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Ion current is found in', '[{"id": "a", "text": "conductors and semi-conductors.", "correct": false}, {"id": "b", "text": "liquids and gasses.", "correct": true}, {"id": "c", "text": "semi-conductors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Electricity conducts through', '[{"id": "a", "text": "vacuum.", "correct": true}, {"id": "b", "text": "solids and liquids only.", "correct": false}, {"id": "c", "text": "solids only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An example of a good electrical insulator is', '[{"id": "a", "text": "aluminium.", "correct": false}, {"id": "b", "text": "glass.", "correct": true}, {"id": "c", "text": "mercury.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Static charges remaining in an aircraft are dissipated by', '[{"id": "a", "text": "earthing the aircraft as soon as possible.", "correct": true}, {"id": "b", "text": "the use of a conducting type nose wheel.", "correct": false}, {"id": "c", "text": "bonding the aircraft to a refuel tanker.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An element could be considered to be a conductor if it has', '[{"id": "a", "text": "a small number of electrons in its outer orbit.", "correct": true}, {"id": "b", "text": "a large number of electrons in its outer orbit.", "correct": false}, {"id": "c", "text": "a large number of electrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A charged body is said to have', '[{"id": "a", "text": "a surplus or deficiency of electrons.", "correct": true}, {"id": "b", "text": "a deficiency of neutrons.", "correct": false}, {"id": "c", "text": "a surplus of protons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The risk of a fire due to static electricity is overcome', '[{"id": "a", "text": "by connecting all metal components by bonding.", "correct": true}, {"id": "b", "text": "by fitting static wicks and isolating the battery from inflammable gas sources.", "correct": false}, {"id": "c", "text": "by fitting static wicks and insulating all metal components.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The purpose of bonding is to', '[{"id": "a", "text": "ensure all components have been securely fitted.", "correct": false}, {"id": "b", "text": "stop different potentials developing with subsequent fire risks.", "correct": true}, {"id": "c", "text": "give generated static an easy return path to the generator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The various parts of an aircraft airframe are maintained at the same potential by', '[{"id": "a", "text": "the supply bus-bars.", "correct": false}, {"id": "b", "text": "bonding.", "correct": true}, {"id": "c", "text": "static discharge wicks.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The resistance of the current return path through the aircraft is always considered negligible, provided the', '[{"id": "a", "text": "structure is adequately bonded.", "correct": true}, {"id": "b", "text": "voltage drop across the circuit is checked.", "correct": false}, {"id": "c", "text": "generator is properly grounded.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If an insulated conductor is placed near to a negatively charged rod, the nearest end of the conductor becomes', '[{"id": "a", "text": "No change will occur.", "correct": false}, {"id": "b", "text": "negatively charged.", "correct": false}, {"id": "c", "text": "positively charged.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The electromagnetic force between two charged bodies is', '[{"id": "a", "text": "inversely proportional to the distance between them.", "correct": false}, {"id": "b", "text": "inversely proportional to the square of the distance between them.", "correct": true}, {"id": "c", "text": "proportional to the distance between them.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a negatively charged conductor is placed next to an insulated rod', '[{"id": "a", "text": "the rod becomes negatively charged.", "correct": false}, {"id": "b", "text": "the rod has no charge.", "correct": false}, {"id": "c", "text": "the rod becomes positively charged.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a photon radiating into an electronic device causes the production of an electron/hole pair, the device is known as a', '[{"id": "a", "text": "light emitting diode.", "correct": false}, {"id": "b", "text": "laser diode.", "correct": false}, {"id": "c", "text": "photodiode.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Faraday’s Law States that', '[{"id": "a", "text": "the magnitude of the EMF is indirectly proportional to the rate of change of flux.", "correct": false}, {"id": "b", "text": "the magnitude of the EMF is directly proportional to the magnetic flux.", "correct": false}, {"id": "c", "text": "the magnitude of the EMF is directly proportional to the rate of change of flux.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which of the following is 1 Amp?', '[{"id": "a", "text": "1000 mA.", "correct": true}, {"id": "b", "text": "1000 kA.", "correct": false}, {"id": "c", "text": "1000 µA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The term that describes the combined resistive forces in an AC circuit is', '[{"id": "a", "text": "resistance.", "correct": false}, {"id": "b", "text": "total resistance.", "correct": false}, {"id": "c", "text": "impedance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Ohm’s law states that:', '[{"id": "a", "text": "m.f. = current divided by resistance.", "correct": false}, {"id": "b", "text": "current = e.m.f. divided by resistance.", "correct": true}, {"id": "c", "text": "resistance = current divided by e.m.f.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'E.M.F. in an electric circuit corresponds to what in a magnetic circuit', '[{"id": "a", "text": "MMF.", "correct": true}, {"id": "b", "text": "reluctance.", "correct": false}, {"id": "c", "text": "flux.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In conventional current flow, what is Fleming’s right hand rule used for?', '[{"id": "a", "text": "Generators.", "correct": true}, {"id": "b", "text": "Motors.", "correct": false}, {"id": "c", "text": "Inductors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The SI unit of work is', '[{"id": "a", "text": "Kilogram metres-force.", "correct": false}, {"id": "b", "text": "Joules per metre.", "correct": false}, {"id": "c", "text": "Joules per second (Watts).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A coulomb is', '[{"id": "a", "text": "one ampere * second.", "correct": true}, {"id": "b", "text": "one second per ampere.", "correct": false}, {"id": "c", "text": "one ampere per second.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A volt can be considered to be a', '[{"id": "a", "text": "unit of electrical power.", "correct": false}, {"id": "b", "text": "quantity of electrical energy.", "correct": false}, {"id": "c", "text": "unit of electrical pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is 3.25 volts in millivolts?', '[{"id": "a", "text": "3,250 millivolts.", "correct": true}, {"id": "b", "text": "325,000 millivolts.", "correct": false}, {"id": "c", "text": "3.25 millivolts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Electromotive force is measured in', '[{"id": "a", "text": "Watts.", "correct": false}, {"id": "b", "text": "Ohms.", "correct": false}, {"id": "c", "text": "Volts.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The basis for transformer operation in the use of alternating current is mutual', '[{"id": "a", "text": "inductance.", "correct": true}, {"id": "b", "text": "capacitance.", "correct": false}, {"id": "c", "text": "reactance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When two coils are linked by a common flux, a voltage can be induced in one by a changing current in the other. This process is known as', '[{"id": "a", "text": "self induction.", "correct": false}, {"id": "b", "text": "the magnetic effect.", "correct": false}, {"id": "c", "text": "mutual induction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When an electrical supply becomes ’open-circuit’', '[{"id": "a", "text": "the fuse or circuit breaker should isolate the circuit due to the increased current drawn.", "correct": false}, {"id": "b", "text": "the loss of continuity will prevent its component from functioning.", "correct": true}, {"id": "c", "text": "the component will operate normally but will not switch off.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The S.I. unit of magnetic flux density is the', '[{"id": "a", "text": "Henry.", "correct": false}, {"id": "b", "text": "Weber.", "correct": false}, {"id": "c", "text": "Tesla.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 1 µF capacitor is equivalent to', '[{"id": "a", "text": "1,000,000 Farads.", "correct": false}, {"id": "b", "text": "000,001 Farads.", "correct": true}, {"id": "c", "text": "001 Farads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The opposition offered by a coil to the flow of alternating current is called (disregarding resistance)', '[{"id": "a", "text": "inductive reactance.", "correct": true}, {"id": "b", "text": "impedance.", "correct": false}, {"id": "c", "text": "reluctance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A shunt is used with', '[{"id": "a", "text": "an ammeter.", "correct": true}, {"id": "b", "text": "a voltmeter.", "correct": false}, {"id": "c", "text": "an ohmmeter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a load in series has a current passing through it, the magnetic field can be worked out by using', '[{"id": "a", "text": "the corkscrew rule.", "correct": true}, {"id": "b", "text": "left hand rule.", "correct": false}, {"id": "c", "text": "right hand rule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The unit for power is', '[{"id": "a", "text": "Joules per second.", "correct": true}, {"id": "b", "text": "N/m.", "correct": false}, {"id": "c", "text": "Volts/Amps.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In conventional flow, the left hand rule applies to', '[{"id": "a", "text": "generators.", "correct": false}, {"id": "b", "text": "batteries.", "correct": false}, {"id": "c", "text": "motors.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When a conductor is cut by magnetic lines of force an EMF is induced. This is', '[{"id": "a", "text": "Lenz’s Law.", "correct": false}, {"id": "b", "text": "Faraday’s Law.", "correct": true}, {"id": "c", "text": "Kirchhoff’s Law.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The Watt can be expressed as', '[{"id": "a", "text": "Seconds per Joule.", "correct": false}, {"id": "b", "text": "Joules * seconds.", "correct": false}, {"id": "c", "text": "Joules per second.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To determine the direction of the magnetic field around a conductor you would use', '[{"id": "a", "text": "Fleming’s right hand rule.", "correct": false}, {"id": "b", "text": "Fleming’s left hand rule.", "correct": false}, {"id": "c", "text": "the corkscrew rule.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Switching on or off the current in one coil produces an emf in another coil adjacent to it. The two coils are said to have', '[{"id": "a", "text": "self inductance.", "correct": false}, {"id": "b", "text": "auto inductance.", "correct": false}, {"id": "c", "text": "mutual inductance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Self induced emf in a coil supplied with a current varying at a uniform rate can be found by', '[{"id": "a", "text": "-L dΦ / dt", "correct": false}, {"id": "b", "text": "-N dI / dt", "correct": false}, {"id": "c", "text": "-L dI / dt", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The property of a material to accept lines of flux is called', '[{"id": "a", "text": "retentivity.", "correct": false}, {"id": "b", "text": "reluctance.", "correct": false}, {"id": "c", "text": "permeability.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Magnetomotive force can be found by', '[{"id": "a", "text": "I * N.", "correct": true}, {"id": "b", "text": "Blv.", "correct": false}, {"id": "c", "text": "N/I.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When a conductor is cut by magnetic lines of force an EMF is induced. This is', '[{"id": "a", "text": "Kirchhoff’s Law.", "correct": false}, {"id": "b", "text": "Faraday’s Law.", "correct": true}, {"id": "c", "text": "Lenz’s Law.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The direction of induced conventional current in a wire rotating in a magnetic field can be determined by', '[{"id": "a", "text": "cork screw rule.", "correct": false}, {"id": "b", "text": "Fleming’s right hand rule.", "correct": true}, {"id": "c", "text": "Fleming’s left hand rule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'How would you find the direction of the electron flow in an armature located in a magnetic field?', '[{"id": "a", "text": "Flemings left hand rule.", "correct": true}, {"id": "b", "text": "Flemings right hand rule.", "correct": false}, {"id": "c", "text": "Maxwells corkscrew rule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the SI unit of conductance?', '[{"id": "a", "text": "Ohm.", "correct": false}, {"id": "b", "text": "Siemen.", "correct": true}, {"id": "c", "text": "Ohm-metre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the SI unit of resistivity?', '[{"id": "a", "text": "Ohms.", "correct": false}, {"id": "b", "text": "Ohm metre.", "correct": true}, {"id": "c", "text": "Ohms/metre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the formula for conductance? (R=Resistance)', '[{"id": "a", "text": "R + 1.", "correct": false}, {"id": "b", "text": "1/R.", "correct": true}, {"id": "c", "text": "1-R.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In electrical circuit, Direct Current power is represented by the', '[{"id": "a", "text": "Ampere.", "correct": false}, {"id": "b", "text": "Watt.", "correct": true}, {"id": "c", "text": "Joule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In S.I. units, work is denoted by', '[{"id": "a", "text": "Newton-meter which is Joules.", "correct": true}, {"id": "b", "text": "Joules/sec which is Watts.", "correct": false}, {"id": "c", "text": "Kilogram-force-meter/sec which is Metric Horsepower.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The unit of energy is the', '[{"id": "a", "text": "Joule.", "correct": true}, {"id": "b", "text": "Watt.", "correct": false}, {"id": "c", "text": "Coulomb.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Potential difference is another term for', '[{"id": "a", "text": "voltage.", "correct": true}, {"id": "b", "text": "charge.", "correct": false}, {"id": "c", "text": "energy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'XL is the symbol of', '[{"id": "a", "text": "inductive reactance.", "correct": true}, {"id": "b", "text": "capacitive reactance.", "correct": false}, {"id": "c", "text": "impedance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Using Ohm’s law', '[{"id": "a", "text": "current is directly proportional to the resistance.", "correct": false}, {"id": "b", "text": "current is directly proportional to the EMF.", "correct": true}, {"id": "c", "text": "resistance is directly proportional to EMF.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'One volt is induced into a circuit with a current varying at 1 amp per second. The circuit has', '[{"id": "a", "text": "1 ampere turn.", "correct": false}, {"id": "b", "text": "1 Tesla.", "correct": false}, {"id": "c", "text": "1 Henry.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The property of a conductor of electricity that limits or restricts the flow of electric current is', '[{"id": "a", "text": "limiter.", "correct": false}, {"id": "b", "text": "resistance.", "correct": true}, {"id": "c", "text": "fuse.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Kirchhoff’s law is applicable to', '[{"id": "a", "text": "parallel networks.", "correct": false}, {"id": "b", "text": "series networks.", "correct": false}, {"id": "c", "text": "closed loop networks.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The SI unit of work is the', '[{"id": "a", "text": "Watt.", "correct": false}, {"id": "b", "text": "Newton Meter.", "correct": false}, {"id": "c", "text": "Joule.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The EMF of a generator can be calculated from which law?', '[{"id": "a", "text": "Faraday’s law.", "correct": true}, {"id": "b", "text": "Kirchhoff’s law.", "correct": false}, {"id": "c", "text": "Lenz’s law.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Thermocouple harnesses are made from the same materials as the thermocouple so that', '[{"id": "a", "text": "mini junctions are not formed.", "correct": true}, {"id": "b", "text": "the resistance is not increased beyond limits.", "correct": false}, {"id": "c", "text": "they will not corrode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A piezoelectric device generates electricity through', '[{"id": "a", "text": "friction.", "correct": false}, {"id": "b", "text": "light.", "correct": false}, {"id": "c", "text": "pressure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A photozoidal cell produces electricity when subjected to', '[{"id": "a", "text": "light.", "correct": true}, {"id": "b", "text": "pressure.", "correct": false}, {"id": "c", "text": "heat.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A thermocouple indicator is basically a type of', '[{"id": "a", "text": "millivoltmeter.", "correct": true}, {"id": "b", "text": "milliammeter.", "correct": false}, {"id": "c", "text": "milliohmeter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A light/heat sensitive cell is a', '[{"id": "a", "text": "transistor.", "correct": false}, {"id": "b", "text": "diode.", "correct": false}, {"id": "c", "text": "transducer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A component that produces an output voltage due to incident light is called a', '[{"id": "a", "text": "liquid crystal.", "correct": false}, {"id": "b", "text": "solar cell.", "correct": true}, {"id": "c", "text": "light emitting diode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The flux density of a magnetic field is 1.5T. The length of the conductor in the field is 2 m and the speed of the conductor is 10 m/s. The EMF induced is', '[{"id": "a", "text": "3 V.", "correct": false}, {"id": "b", "text": "5 V.", "correct": false}, {"id": "c", "text": "30 V.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A conductor is placed in a magnetised coil. What will happen?', '[{"id": "a", "text": "Nothing will happen unless the conductor is moved.", "correct": true}, {"id": "b", "text": "The conductor will move.", "correct": false}, {"id": "c", "text": "A force will be created.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The maximum output voltage from a basic single loop generator is when the loop is', '[{"id": "a", "text": "rotating anti-clockwise relative to the direction of the magnetic flux.", "correct": false}, {"id": "b", "text": "cutting maximum lines of magnetic flux.", "correct": true}, {"id": "c", "text": "at 45° to the magnetic flux.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 20 cell battery with each cell having an internal resistance of 0.1 ohms is charged with 2 leads having a total resistance of 0.1 ohms. The battery is charged with a current of 5 amps. What is the charging voltage ?', '[{"id": "a", "text": "0.5 volts.", "correct": false}, {"id": "b", "text": "10.5 volts.", "correct": true}, {"id": "c", "text": "0.05 volts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two 10V, 20 Ah batteries are connected in parallel and connected across a 10 ohm load. How long could they supply normal current before the voltage begins to decay?', '[{"id": "a", "text": "40 hours.", "correct": true}, {"id": "b", "text": "20 hours.", "correct": false}, {"id": "c", "text": "4 hours.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A battery rated at 40 Ah will supply 200 mA for', '[{"id": "a", "text": "200 hours.", "correct": true}, {"id": "b", "text": "20 hours.", "correct": false}, {"id": "c", "text": "5 hours.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A zinc-carbon battery life depends upon', '[{"id": "a", "text": "the amount of zinc.", "correct": true}, {"id": "b", "text": "the purity of the carbon rod.", "correct": false}, {"id": "c", "text": "the amount of the electrolyte paste.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When checking the SG of the electrolyte in a lead acid battery, you should', '[{"id": "a", "text": "check any cell because they will all be the same.", "correct": false}, {"id": "b", "text": "check only the no. 1 cell because it is the master cell.", "correct": false}, {"id": "c", "text": "check all cells because they may be different.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The PD at the terminals of an open circuit battery with a small internal resistance will be', '[{"id": "a", "text": "more than the EMF.", "correct": false}, {"id": "b", "text": "less than the EMF.", "correct": false}, {"id": "c", "text": "the same as the EMF.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An accumulation of hydrogen on the plates of a battery is known as', '[{"id": "a", "text": "polarization.", "correct": true}, {"id": "b", "text": "ionization.", "correct": false}, {"id": "c", "text": "hydration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What part of a battery is covered in hydrogen during polarization?', '[{"id": "a", "text": "Anode.", "correct": false}, {"id": "b", "text": "Both the anode and the cathode.", "correct": false}, {"id": "c", "text": "Cathode.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which of the following is most likely to cause thermal runaway in a nickel-cadmium battery?', '[{"id": "a", "text": "A high internal resistance condition.", "correct": false}, {"id": "b", "text": "High current charging of the battery to more than 100 percent of its capacity.", "correct": true}, {"id": "c", "text": "Excessive current draw from the battery.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The method of ascertaining the voltage of a standard aircraft lead-acid battery is by checking', '[{"id": "a", "text": "the voltage with rated load switched ON.", "correct": true}, {"id": "b", "text": "the voltage on open circuit.", "correct": false}, {"id": "c", "text": "the voltage off load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two batteries 12 V and 40 Ah each, are in series. What is the total capacity?', '[{"id": "a", "text": "12 V 80 Ah.", "correct": false}, {"id": "b", "text": "24 V 40 Ah.", "correct": true}, {"id": "c", "text": "24 V 80Ah.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a battery has got low internal resistance, then the', '[{"id": "a", "text": "no load voltage will be the same as on load voltage.", "correct": true}, {"id": "b", "text": "on load voltage will be greater than no load voltage.", "correct": false}, {"id": "c", "text": "no load voltage will be greater than on load voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Conventional current flow inside a battery is from', '[{"id": "a", "text": "either anode to cathode or cathode to anode, depending on the active elements.", "correct": false}, {"id": "b", "text": "cathode to anode.", "correct": false}, {"id": "c", "text": "anode to cathode.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a voltaic cell, what is the build-up on the cathode called?', '[{"id": "a", "text": "Hydration.", "correct": false}, {"id": "b", "text": "Polarization.", "correct": true}, {"id": "c", "text": "Sulphation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two 12 V 40 amp hour batteries connected in parallel will produce', '[{"id": "a", "text": "24 V 80 ah.", "correct": false}, {"id": "b", "text": "12 V 80 ah.", "correct": true}, {"id": "c", "text": "24 V 40 ah.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 24-volt source is required to furnish 48 watts to a parallel circuit consisting of four resistors of equal value. What is the voltage drop across each resistor?', '[{"id": "a", "text": "12 volts.", "correct": false}, {"id": "b", "text": "24 volts.", "correct": true}, {"id": "c", "text": "3 volts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The method of ascertaining the voltage of a standard aircraft lead-acid battery is by checking', '[{"id": "a", "text": "the voltage on open circuit.", "correct": false}, {"id": "b", "text": "the voltage off load.", "correct": false}, {"id": "c", "text": "the voltage with rated load switched ON.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two similar 12v batteries connected in parallel will produce', '[{"id": "a", "text": "24v e.m.f. with the same capacity as each battery.", "correct": false}, {"id": "b", "text": "12 V e.m.f. with twice the capacity of each battery.", "correct": true}, {"id": "c", "text": "24 V e.m.f. with twice the capacity of each battery", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The voltage of a secondary cell is', '[{"id": "a", "text": "determined by the active materials on the plates.", "correct": true}, {"id": "b", "text": "determined by the number of plates.", "correct": false}, {"id": "c", "text": "determined by the area of the plates.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the ampere-hour rating of a storage battery that is designed to deliver 45 amperes for 2.5 hours?', '[{"id": "a", "text": "90 ampere-hour.", "correct": false}, {"id": "b", "text": "112.5 ampere-hour.", "correct": true}, {"id": "c", "text": "45 ampere-hour.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a nicad battery is not to be used immediately it should be stored', '[{"id": "a", "text": "dry.", "correct": false}, {"id": "b", "text": "fully charged.", "correct": false}, {"id": "c", "text": "fully dissipated.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a mercury cell the steel casing is', '[{"id": "a", "text": "the negative terminal.", "correct": false}, {"id": "b", "text": "neither.", "correct": false}, {"id": "c", "text": "the positive terminal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To improve the life of a dry cell it would be manufactured with', '[{"id": "a", "text": "more electrolyte paste.", "correct": false}, {"id": "b", "text": "more zinc.", "correct": true}, {"id": "c", "text": "a pure carbon positive rod.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a simple voltaic cell the collection of ions on the cathode causes', '[{"id": "a", "text": "polarisation.", "correct": true}, {"id": "b", "text": "sulphation.", "correct": false}, {"id": "c", "text": "hydration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The electrolyte in a nicad battery would rise if the battery was', '[{"id": "a", "text": "remaining at constant voltage.", "correct": false}, {"id": "b", "text": "charging.", "correct": true}, {"id": "c", "text": "discharging.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two 2 volt 10AH cells are connected in series, the output voltage and the capacity would be', '[{"id": "a", "text": "4 volt 10 AH.", "correct": true}, {"id": "b", "text": "4 volt 20 AH.", "correct": false}, {"id": "c", "text": "2 volt, 20 AH.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The electrolyte in a nicad battery is', '[{"id": "a", "text": "potassium hydroxide.", "correct": true}, {"id": "b", "text": "nickel hydroxide.", "correct": false}, {"id": "c", "text": "cadmium hydroxide.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a Leclanche cell the plates are made of', '[{"id": "a", "text": "mercury and lithium.", "correct": false}, {"id": "b", "text": "nickel and cadmium.", "correct": false}, {"id": "c", "text": "zinc and carbon.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a simple voltaic cell, polarization reduces output voltage because of the', '[{"id": "a", "text": "build up of hydrogen on the cathode.", "correct": true}, {"id": "b", "text": "transfer of material between the anode and the cathode.", "correct": false}, {"id": "c", "text": "build up of hydrogen on the anode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When the temperature of the electrolyte in a battery increases, the SG', '[{"id": "a", "text": "remains the same.", "correct": false}, {"id": "b", "text": "goes up.", "correct": false}, {"id": "c", "text": "goes down.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The Daniel Cell electrodes are', '[{"id": "a", "text": "copper and zinc.", "correct": true}, {"id": "b", "text": "carbon and zinc.", "correct": false}, {"id": "c", "text": "zinc and manganese dioxide.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a thermocouple, where is voltage measured?', '[{"id": "a", "text": "At both junctions.", "correct": false}, {"id": "b", "text": "At the hot junction.", "correct": false}, {"id": "c", "text": "At the cold junction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Mercury cells are covered with a metal cover', '[{"id": "a", "text": "as a protective cover.", "correct": false}, {"id": "b", "text": "as a negative terminal.", "correct": false}, {"id": "c", "text": "as a positive terminal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The capacity of a battery is measured in', '[{"id": "a", "text": "volts.", "correct": false}, {"id": "b", "text": "ampere-hours.", "correct": true}, {"id": "c", "text": "cubic centimetres.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A battery’s internal resistance is determined by (OCV = Open Circuit Voltage, CCV = Closed Circuit Voltage)', '[{"id": "a", "text": "IR = (OCV – CCV)/ i.", "correct": true}, {"id": "b", "text": "IR = (OCV + CCV) / i.", "correct": false}, {"id": "c", "text": "IR = (OCV - CCV) / V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'There are more negative than positive plates in a lead acid battery because', '[{"id": "a", "text": "it is necessary for chemical action to take place.", "correct": false}, {"id": "b", "text": "it reduces the internal resistance of the cell.", "correct": false}, {"id": "c", "text": "the positive plates are prone to warping if the chemical action is taking place only on one side.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the approximate internal resistance of a Leclanche cell?', '[{"id": "a", "text": "0.02 ohms - 4 ohms.", "correct": true}, {"id": "b", "text": "6 ohms - 10 ohms.", "correct": false}, {"id": "c", "text": "20 ohms - 30 ohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An aircraft battery on charge from the aircraft generators causes', '[{"id": "a", "text": "internal resistance of the battery to decrease in sympathy with the decreasing charging current.", "correct": false}, {"id": "b", "text": "battery voltage to increases to nominal voltage and the charge current decreases.", "correct": true}, {"id": "c", "text": "battery voltage to decrease to zero until it is fully charged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What effect does hydrogen have in a battery cell?', '[{"id": "a", "text": "Sulphation.", "correct": false}, {"id": "b", "text": "Nothing.", "correct": false}, {"id": "c", "text": "Polarization.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To generate electricity with a fuel cell, you need a constant supply of', '[{"id": "a", "text": "Nitrogen & Sunlight.", "correct": false}, {"id": "b", "text": "Oxygen & Hydrogen.", "correct": true}, {"id": "c", "text": "Kerosene & Heat.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A ni-cad battery found to be below normal capacity should', '[{"id": "a", "text": "have its electrolyte adjusted.", "correct": false}, {"id": "b", "text": "be removed and used for ground use only.", "correct": false}, {"id": "c", "text": "be re-charged with a freshening charge.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In cold weather, to prevent the electrolyte freezing, a battery must be kept', '[{"id": "a", "text": "fully charged.", "correct": true}, {"id": "b", "text": "does not matter.", "correct": false}, {"id": "c", "text": "fully discharged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The internal resistance of a battery off load compared to on load is', '[{"id": "a", "text": "the same.", "correct": false}, {"id": "b", "text": "increased.", "correct": true}, {"id": "c", "text": "decreased.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two 12V, 40Ah cells in series gives', '[{"id": "a", "text": "24 V 80Ah.", "correct": false}, {"id": "b", "text": "12 V 40Ah.", "correct": false}, {"id": "c", "text": "24 V 40Ah.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 24 V 40AH battery discharges at 200mA. How long will it last?', '[{"id": "a", "text": "400 hours.", "correct": false}, {"id": "b", "text": "300 hours.", "correct": false}, {"id": "c", "text": "200 hours.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The electrolyte level of a ni-cad battery', '[{"id": "a", "text": "falls during charge.", "correct": false}, {"id": "b", "text": "falls during discharge.", "correct": true}, {"id": "c", "text": "rises during discharge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When light energises a component, what is the component?', '[{"id": "a", "text": "Light emitting diode.", "correct": false}, {"id": "b", "text": "Photodiode.", "correct": true}, {"id": "c", "text": "Laser diode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Formation of white crystals of potassium carbonate on a properly serviced Ni-cd battery indicates', '[{"id": "a", "text": "over charged.", "correct": true}, {"id": "b", "text": "full charged.", "correct": false}, {"id": "c", "text": "under charged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Thermal runaway causes', '[{"id": "a", "text": "violent gassing only.", "correct": false}, {"id": "b", "text": "violent gassing, boiling of electrolyte and melting of plates and casing.", "correct": true}, {"id": "c", "text": "no gassing, but boiling of electrolyte and melting of plates and casing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A primary cell', '[{"id": "a", "text": "can not recharged.", "correct": true}, {"id": "b", "text": "can be recharged but only a few times.", "correct": false}, {"id": "c", "text": "can be recharged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the insulation resistance of a lead/acid battery is down, it indicates', '[{"id": "a", "text": "case leakage.", "correct": true}, {"id": "b", "text": "leakage between positive and negative terminals.", "correct": false}, {"id": "c", "text": "intercell leakage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When the battery is connected to the aircraft, which terminal should you connect first?', '[{"id": "a", "text": "Any.", "correct": false}, {"id": "b", "text": "Positive.", "correct": true}, {"id": "c", "text": "Negative.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An ammeter in a battery charging system is for the purpose of indicating the', '[{"id": "a", "text": "rate of current used to charge the battery.", "correct": true}, {"id": "b", "text": "amperage available for use.", "correct": false}, {"id": "c", "text": "total amperes being used in the aeroplane.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'For how many hours will a 140AH battery deliver 15A?', '[{"id": "a", "text": "9.33 hours.", "correct": true}, {"id": "b", "text": "27.25 hours.", "correct": false}, {"id": "c", "text": "15.15 hours.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What part of a nickel-cadmium cell helps to prevent thermal runaway?', '[{"id": "a", "text": "The separator.", "correct": true}, {"id": "b", "text": "The negative plate.", "correct": false}, {"id": "c", "text": "The positive plate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When charging current is applied to a nickel-cadmium battery, the cells emit gas only', '[{"id": "a", "text": "when the electrolyte level is low.", "correct": false}, {"id": "b", "text": "if the cells are defective.", "correct": false}, {"id": "c", "text": "toward the end of the charging cycle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the internal resistance of a battery?', '[{"id": "a", "text": "The resistance measured across the two terminals.", "correct": false}, {"id": "b", "text": "The resistance measured when the battery is half charged.", "correct": false}, {"id": "c", "text": "The resistance present inside the battery while connected to a load.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A potential difference of 50 volts produces a current of 10 milliamperes through a resistance of', '[{"id": "a", "text": "500 ohms.", "correct": false}, {"id": "b", "text": "5 ohms.", "correct": false}, {"id": "c", "text": "5,000 ohms.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A conductor with a positive Q (charge) of 4C has 12.56 × 10¹⁸ electrons added to it. It will have aQ=', '[{"id": "a", "text": "6.", "correct": false}, {"id": "b", "text": "2.", "correct": true}, {"id": "c", "text": "0.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A circuit has a current flow of 6A. If the voltage is trebled, the new current will be', '[{"id": "a", "text": "6A.", "correct": false}, {"id": "b", "text": "18A.", "correct": true}, {"id": "c", "text": "2A.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 10 V battery supplies a resistive load of 10 ohms for 1 minute. What is the work done?', '[{"id": "a", "text": "60J.", "correct": false}, {"id": "b", "text": "600J.", "correct": true}, {"id": "c", "text": "10J.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A galvanometer measures', '[{"id": "a", "text": "millivolts.", "correct": false}, {"id": "b", "text": "megohms.", "correct": false}, {"id": "c", "text": "milliamps.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A loss of electrical insulation results in', '[{"id": "a", "text": "an open circuit between the supply and earth.", "correct": false}, {"id": "b", "text": "a short circuit between the supply and earth.", "correct": true}, {"id": "c", "text": "an open circuit in the supply.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 3, 5 and 2 ohms resistance is connected in series with a 10 V battery. The voltage across the 2 ohms resistor is', '[{"id": "a", "text": "2 V.", "correct": true}, {"id": "b", "text": "10V.", "correct": false}, {"id": "c", "text": "4 V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the PD of a circuit which has a 40 mA current and a 1 kilohm resistance?', '[{"id": "a", "text": "40 V.", "correct": true}, {"id": "b", "text": "400 V.", "correct": false}, {"id": "c", "text": "4 V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Three branches in a circuit have currents entering of 3A, 4 A and 5A. A forth branch has 10 A leaving. A fifth branch must have', '[{"id": "a", "text": "22 A leaving.", "correct": false}, {"id": "b", "text": "2 A leaving.", "correct": true}, {"id": "c", "text": "2 A entering.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a circuit containing three resistors of equal value connected in parallel, one resistor goes open circuit. The current in the other two resistors will', '[{"id": "a", "text": "decrease.", "correct": false}, {"id": "b", "text": "increase.", "correct": false}, {"id": "c", "text": "remain the same.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), '20 amperes flow for 20 seconds. How many coulombs have flowed?', '[{"id": "a", "text": "400", "correct": true}, {"id": "b", "text": "20", "correct": false}, {"id": "c", "text": "1", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the resistance of an electrical circuit is increased', '[{"id": "a", "text": "the current will increase.", "correct": false}, {"id": "b", "text": "the voltage will increase.", "correct": false}, {"id": "c", "text": "the current will decrease.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If 2 coulombs flowed through a circuit in 2 seconds, the circuit would have', '[{"id": "a", "text": "1 amp.", "correct": true}, {"id": "b", "text": "2 volts PD.", "correct": false}, {"id": "c", "text": "4 amps.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the voltage across a resistor is doubled', '[{"id": "a", "text": "the current is doubled.", "correct": true}, {"id": "b", "text": "the current is halved.", "correct": false}, {"id": "c", "text": "the resistance is halved.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The total current flowing in a circuit of 200 lamps in parallel, each of a resistance of 400 ohm and connected across an input of 100 volts is', '[{"id": "a", "text": "25 amps.", "correct": false}, {"id": "b", "text": "50 amps.", "correct": true}, {"id": "c", "text": "40 amps.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the cross-sectional area of a conductor is doubled, with voltage constant, the current will', '[{"id": "a", "text": "remain constant.", "correct": false}, {"id": "b", "text": "double.", "correct": true}, {"id": "c", "text": "halve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If two resistors of 5 and 10 ohm respectively are connected in series and the current in the 5 ohm resistor is 1A. what is the current in the 10 ohm resistor?', '[{"id": "a", "text": "1 amp.", "correct": true}, {"id": "b", "text": "It cannot be found without knowing the applied voltage.", "correct": false}, {"id": "c", "text": "1/3 amp.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The voltage in a series circuit', '[{"id": "a", "text": "is different in each component.", "correct": true}, {"id": "b", "text": "is the same in each component.", "correct": false}, {"id": "c", "text": "is less than it would be in a parallel circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If voltage is 100V, resistance is 25 ohms, what is the current?', '[{"id": "a", "text": "4 amperes.", "correct": true}, {"id": "b", "text": "0.4 amperes.", "correct": false}, {"id": "c", "text": "2500 amperes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A short circuit between the supply and earth', '[{"id": "a", "text": "is not dangerous as the current drawn will be low.", "correct": false}, {"id": "b", "text": "does not matter if the circuit uses the aircraft earth as a return.", "correct": false}, {"id": "c", "text": "could be very dangerous as the current drawn will be very high.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A circuit consists of 3 ohm, 5 ohm and 12 ohm resistors in series. The current flowing in the 5 ohm resistor is 10 amps. What is the applied voltage?', '[{"id": "a", "text": "10 V.", "correct": false}, {"id": "b", "text": "100 V.", "correct": false}, {"id": "c", "text": "200 V.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two resistors are connected in series and have an e.m.f. of V volts across them. If the voltages across the resistances are V1 and V2 then by Kirchhoff’s law', '[{"id": "a", "text": "V2 = V1 + V.", "correct": false}, {"id": "b", "text": "V1 = V2 + V.", "correct": false}, {"id": "c", "text": "V = V1 + V2.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A voltmeter is connected', '[{"id": "a", "text": "in parallel.", "correct": true}, {"id": "b", "text": "in series or parallel.", "correct": false}, {"id": "c", "text": "in series.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Since electrical supplies taken from a bus-bar are in parallel, isolating some of the services would', '[{"id": "a", "text": "reduce the current consumption from the bus-bar.", "correct": true}, {"id": "b", "text": "increase the current consumption from the bus-bar.", "correct": false}, {"id": "c", "text": "not affect the current consumption, it would reduce the voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The current flowing through a circuit can be increased to four times its original value by', '[{"id": "a", "text": "doubling the applied voltage and halving the resistance.", "correct": true}, {"id": "b", "text": "doubling the resistance and doubling the applied voltage.", "correct": false}, {"id": "c", "text": "halving the applied voltage and halving the resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a circuit containing three resistors of equal value connected in series and one of the resistors short circuits, the effect is for the current in the other two resistors to', '[{"id": "a", "text": "decrease.", "correct": false}, {"id": "b", "text": "increase.", "correct": true}, {"id": "c", "text": "remain the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a series resistive circuit', '[{"id": "a", "text": "the total voltage is equal to the sum of the individual voltages.", "correct": true}, {"id": "b", "text": "the total voltage is the same as the highest individual.", "correct": false}, {"id": "c", "text": "the total voltage equals the difference between the individual voltages.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An ammeter is connected into a circuit in', '[{"id": "a", "text": "series.", "correct": true}, {"id": "b", "text": "shunt.", "correct": false}, {"id": "c", "text": "parallel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a balanced Wheatstone bridge, across the centre of the bridge there is', '[{"id": "a", "text": "current and voltage at maximum.", "correct": false}, {"id": "b", "text": "no current flow.", "correct": true}, {"id": "c", "text": "no voltage present at either end.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 24 V battery has an internal resistance of 1 ohm. When connected to a load, 12 amps flows. The value of the load is', '[{"id": "a", "text": "12 ohms.", "correct": false}, {"id": "b", "text": "1/2 ohm.", "correct": false}, {"id": "c", "text": "1 ohm.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A parallel circuit with any number of 2 terminal connections', '[{"id": "a", "text": "the individual voltage drops is equal to the emf.", "correct": true}, {"id": "b", "text": "has the same current throughout.", "correct": false}, {"id": "c", "text": "the resistance is dependent on current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To find the internal resistance of a battery in a circuit of known current', '[{"id": "a", "text": "use the formula R = V * I.", "correct": false}, {"id": "b", "text": "find the lost volts of the circuit.", "correct": true}, {"id": "c", "text": "find the emf of the circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a series circuit with 3 resistors, the current is', '[{"id": "a", "text": "lower than the smallest.", "correct": false}, {"id": "b", "text": "the total of all 3 using ohms law to find the current.", "correct": false}, {"id": "c", "text": "even in all 3.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which is not thermally operated?', '[{"id": "a", "text": "A limiting resistor.", "correct": true}, {"id": "b", "text": "A current limiter.", "correct": false}, {"id": "c", "text": "A fuse.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a Desynn indicator system, the rotor is', '[{"id": "a", "text": "an electromagnet.", "correct": false}, {"id": "b", "text": "a permanent magnet.", "correct": true}, {"id": "c", "text": "an AC magnet.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A load that is subject to a potential difference with a current running through it will have a magnetic field around it with the magnitude and direction of the field determined by the corkscrew', '[{"id": "a", "text": "rule.", "correct": false}, {"id": "b", "text": "dissipate power in the form of heat.", "correct": true}, {"id": "c", "text": "will move in a direction shown by the right hand rule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The resistance of a material is', '[{"id": "a", "text": "independent of the material type.", "correct": false}, {"id": "b", "text": "the same as its conductance.", "correct": false}, {"id": "c", "text": "the reciprocal of its conductance.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Resistance is measured using what unit of temperature?', '[{"id": "a", "text": "Absolute.", "correct": true}, {"id": "b", "text": "Centigrade.", "correct": false}, {"id": "c", "text": "Fahrenheit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A resistor has 4 bands on it coloured blue, yellow, yellow, gold. It’s value is', '[{"id": "a", "text": "640 kΩ ± 5%.", "correct": true}, {"id": "b", "text": "4 MΩ ± 10%.", "correct": false}, {"id": "c", "text": "64 kΩ ± 5%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The electron flow through a conductor will be decreased the most if the cross sectional area', '[{"id": "a", "text": "is decreased and the length is increased.", "correct": true}, {"id": "b", "text": "and the length are both decreased.", "correct": false}, {"id": "c", "text": "and the length are both increased.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Small resistors too small or mis-shapen for the application of colour are marked instead using', '[{"id": "a", "text": "an abbreviated resistance value.", "correct": false}, {"id": "b", "text": "a letter code.", "correct": true}, {"id": "c", "text": "a dot code.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Total resistance in a parallel resistor circuit, of R1 and R2 is', '[{"id": "a", "text": "RT = 1/R1 + 1/R2.", "correct": false}, {"id": "b", "text": "1/RT = (R1 * R2) ÷ (R1 + R2).", "correct": false}, {"id": "c", "text": "1/RT = 1/R1 + 1/R2.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the resistance of a resistor which is in series with two other resistors is doubled', '[{"id": "a", "text": "the current in that resistance is doubled.", "correct": false}, {"id": "b", "text": "the volts drop across that resistor increases.", "correct": true}, {"id": "c", "text": "the current in that resistance is halved.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Potentiometers are used as a', '[{"id": "a", "text": "variable voltage source.", "correct": true}, {"id": "b", "text": "variable resistor.", "correct": false}, {"id": "c", "text": "variable current source.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a Wheatstone Bridge, the ammeter reads zero, and the variable resistor is adjusted to 5 ohms. Resistor P has a value of 10 ohms and Q has a value of 100 ohms. What is the value of the unknown resistor?', '[{"id": "a", "text": "5 ohms.", "correct": false}, {"id": "b", "text": "0.5 ohms.", "correct": false}, {"id": "c", "text": "50 ohms.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In general, increasing the cross sectional area of an electrical cable', '[{"id": "a", "text": "increases its resistance.", "correct": false}, {"id": "b", "text": "enables it to carry more voltage.", "correct": false}, {"id": "c", "text": "enables it to carry more current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Six resistors each of 6 ohms would be', '[{"id": "a", "text": "1 ohm in series.", "correct": false}, {"id": "b", "text": "1 ohm in parallel.", "correct": true}, {"id": "c", "text": "36 ohms in parallel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A potentiometer varies', '[{"id": "a", "text": "resistance.", "correct": false}, {"id": "b", "text": "current.", "correct": false}, {"id": "c", "text": "voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The formula for resistance in series is', '[{"id": "a", "text": "RT = R1 + R2 + R3 + ... + Rn", "correct": true}, {"id": "b", "text": "RT = R1 * R2 * R3 * ... * Rn", "correct": false}, {"id": "c", "text": "1/RT = 1/( R1 * R2 * R3 * ... * Rn)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the combined value of resistances of 4 ohm and 6 ohm connected in parallel?', '[{"id": "a", "text": "2.4 ohm.", "correct": true}, {"id": "b", "text": "0.24 ohm.", "correct": false}, {"id": "c", "text": "24 ohm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a number of resistors are connected in parallel, the total resistance is', '[{"id": "a", "text": "smaller than the lowest.", "correct": true}, {"id": "b", "text": "the same as the lowest.", "correct": false}, {"id": "c", "text": "greater than the lowest.", "correct": false}]'::jsonb, '{B1,B2}'),
