    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A capacitor rating is', '[{"id": "a", "text": "the voltage it will charge to.", "correct": false}, {"id": "b", "text": "the maximum continuous voltage it can take.", "correct": true}, {"id": "c", "text": "the voltage it will rupture at.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The multiplier colour coding on a capacitor is in', '[{"id": "a", "text": "picofarads.", "correct": true}, {"id": "b", "text": "farads.", "correct": false}, {"id": "c", "text": "microfarads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When a capacitor is charged from a DC supply, the voltage/time curve is', '[{"id": "a", "text": "logarithmic.", "correct": false}, {"id": "b", "text": "linear.", "correct": false}, {"id": "c", "text": "exponential.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An electrolytic capacitor is used because it has a', '[{"id": "a", "text": "small physical size for low leakage current.", "correct": false}, {"id": "b", "text": "large physical size for a large capacity.", "correct": false}, {"id": "c", "text": "small physical size for a large capacity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An electrolytic capacitor would be used in circuits supplying', '[{"id": "a", "text": "heavy loads.", "correct": true}, {"id": "b", "text": "light loads.", "correct": false}, {"id": "c", "text": "heavy / light loads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 20 Picofarad capacitor with a 1 Megohm resistor takes how long to charge?', '[{"id": "a", "text": "100 microseconds.", "correct": true}, {"id": "b", "text": "20 milliseconds.", "correct": false}, {"id": "c", "text": "1 second.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The discharge curve of a capacitor is', '[{"id": "a", "text": "Exponential.", "correct": true}, {"id": "b", "text": "Logarithmic.", "correct": false}, {"id": "c", "text": "Linear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the value of a monolithic capacitor with 103 on it?', '[{"id": "a", "text": "1000pf.", "correct": false}, {"id": "b", "text": "10,000pf.", "correct": true}, {"id": "c", "text": "100,000pf.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the formula for working out the capacitance of a capacitor if K = dielectric constant, A = area of the plates, d = distance plates apart?', '[{"id": "a", "text": "c = K*A/d.", "correct": true}, {"id": "b", "text": "c = d/K*A.", "correct": false}, {"id": "c", "text": "c = K*d/A.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Total capacitance of 3 capacitors each 12milliFarad in a parallel circuit', '[{"id": "a", "text": "36milliFarad.", "correct": true}, {"id": "b", "text": "12milliFarad.", "correct": false}, {"id": "c", "text": "6mf.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A combination of 1 megohm and 8 microfarad would give a time constant of', '[{"id": "a", "text": "40 seconds.", "correct": false}, {"id": "b", "text": "400 ms.", "correct": false}, {"id": "c", "text": "8 seconds.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Generally, what is the voltage across a fully charged capacitor?', '[{"id": "a", "text": "Less than circuit voltage.", "correct": false}, {"id": "b", "text": "Same as circuit voltage.", "correct": true}, {"id": "c", "text": "More than circuit voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When would you use an electrolytic capacitor?', '[{"id": "a", "text": "On a balanced circuit.", "correct": false}, {"id": "b", "text": "Low output compared to size required.", "correct": false}, {"id": "c", "text": "Large output compared to size required.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A capacitor has Brown, Black and Orange bands. It’s value is', '[{"id": "a", "text": "10 picofarads.", "correct": false}, {"id": "b", "text": "10 nanofarads.", "correct": true}, {"id": "c", "text": "100 picofarads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Voltage measured between the plates of a capacitor will be generally', '[{"id": "a", "text": "can dangerously higher than applied voltage.", "correct": false}, {"id": "b", "text": "the same as applied voltage.", "correct": true}, {"id": "c", "text": "less than applied voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Dielectric constant of a capacitor is', '[{"id": "a", "text": "max V that can be applied to a capacitor.", "correct": false}, {"id": "b", "text": "electrostatic storing capability of the dielectric.", "correct": true}, {"id": "c", "text": "max I stored in the capacitor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'One microfarad is', '[{"id": "a", "text": "1 * 10^-12 farads.", "correct": false}, {"id": "b", "text": "1 * 10^12 farads.", "correct": false}, {"id": "c", "text": "1 * 10^-6 farads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A circuit with a capacitor has 6 volts applied to it with a charge of 2400 pico-coulombs. What would the charge be if the applied voltage was 1.5 volts ?', '[{"id": "a", "text": "2400 * 10^-12 coulombs.", "correct": false}, {"id": "b", "text": "600 * 10^-9 coulombs.", "correct": false}, {"id": "c", "text": "600 * 10^-12 coulombs.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a capacitor, the dielectric strength is measured in', '[{"id": "a", "text": "Farads per meter.", "correct": false}, {"id": "b", "text": "Volts per metre.", "correct": true}, {"id": "c", "text": "Coulombs per m2.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Three capacitors connected in series, each having a value of 12 picofarads, calculate the total capacitance', '[{"id": "a", "text": "36 picofarads.", "correct": false}, {"id": "b", "text": "4 picofarads.", "correct": true}, {"id": "c", "text": "12 picofarads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Magnetic inclination is the least at the', '[{"id": "a", "text": "poles.", "correct": false}, {"id": "b", "text": "equator.", "correct": true}, {"id": "c", "text": "isoclines.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Ferromagnetic materials can be magnetized', '[{"id": "a", "text": "below a certain temperature.", "correct": true}, {"id": "b", "text": "above a certain temperature.", "correct": false}, {"id": "c", "text": "within a band of temperatures.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Glass is an example of a', '[{"id": "a", "text": "coercive material.", "correct": false}, {"id": "b", "text": "paramagnetic material.", "correct": true}, {"id": "c", "text": "diamagnetic material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A solenoid of 10 turns per metre carries a current of 5A. If the current is reduced to 2.5A, how many turns would be required to maintain the same magnetic field?', '[{"id": "a", "text": "20.", "correct": true}, {"id": "b", "text": "50.", "correct": false}, {"id": "c", "text": "5.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which of the following materials is easiest to magnetize?', '[{"id": "a", "text": "High grade steel.", "correct": false}, {"id": "b", "text": "Soft iron.", "correct": true}, {"id": "c", "text": "Cast iron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To find which end of an electromagnet is the north pole, use the', '[{"id": "a", "text": "Fleming’s Left Hand Rule.", "correct": false}, {"id": "b", "text": "Right Hand Clasp Rule.", "correct": true}, {"id": "c", "text": "Cork Screw Rule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The earth’s magnetic field is greatest at the', '[{"id": "a", "text": "magnetic equator.", "correct": false}, {"id": "b", "text": "geographic poles.", "correct": false}, {"id": "c", "text": "magnetic poles.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The lines of magnetic flux from a magnet will', '[{"id": "a", "text": "attract each other.", "correct": false}, {"id": "b", "text": "repel each other.", "correct": true}, {"id": "c", "text": "have no effect upon each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Of the following which pair of materials would most readily become magnetized?', '[{"id": "a", "text": "Iron and steel.", "correct": true}, {"id": "b", "text": "Copper and steel.", "correct": false}, {"id": "c", "text": "Nickel and bronze.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The core material used for an electromagnet is soft iron because', '[{"id": "a", "text": "its magnetism is not easily destroyed.", "correct": false}, {"id": "b", "text": "it retains most of its flux density when demagnetized.", "correct": false}, {"id": "c", "text": "it demagnetizes easily.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the North pole of a magnet is brought nearer to the North pole of another magnet', '[{"id": "a", "text": "attraction between them will be increased.", "correct": false}, {"id": "b", "text": "repulsion between them will be reduced.", "correct": false}, {"id": "c", "text": "repulsion between them will be increased.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Where is the magnetic dip least?', '[{"id": "a", "text": "Poles.", "correct": false}, {"id": "b", "text": "Isoclinals.", "correct": false}, {"id": "c", "text": "Equator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When a number of ferrite pieces are grouped together, they', '[{"id": "a", "text": "are semi-permanent magnets when DC is passed through them.", "correct": false}, {"id": "b", "text": "are electromagnets.", "correct": false}, {"id": "c", "text": "can be used to store binary code.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Ampere turns is calculated by the number of turns', '[{"id": "a", "text": "multiplied by current.", "correct": true}, {"id": "b", "text": "divided by current.", "correct": false}, {"id": "c", "text": "multiplied by magnetic flux.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The unit of flux is the', '[{"id": "a", "text": "Ampere turns / metre.", "correct": false}, {"id": "b", "text": "Weber.", "correct": true}, {"id": "c", "text": "Ampere turns.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Lines of magnetic flux pass from', '[{"id": "a", "text": "South to North.", "correct": false}, {"id": "b", "text": "East to West.", "correct": false}, {"id": "c", "text": "North to South.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Why is ferrite used in memory circuits?', '[{"id": "a", "text": "High reluctance.", "correct": false}, {"id": "b", "text": "Low permeability.", "correct": false}, {"id": "c", "text": "High remanence.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Magnetic lines are flowing parallel. They will', '[{"id": "a", "text": "have no effect on each other.", "correct": false}, {"id": "b", "text": "attract each other.", "correct": false}, {"id": "c", "text": "repel each other.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The horizontal component of the earth’s magnetic field is most strongly felt at', '[{"id": "a", "text": "equator.", "correct": true}, {"id": "b", "text": "45 degrees latitude.", "correct": false}, {"id": "c", "text": "poles.", "correct": false}]'::jsonb, '{B1,B2}'),
