    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Magnetic field on a solenoid is', '[{"id": "a", "text": "the same both inside and outside the coil.", "correct": false}, {"id": "b", "text": "weakest outside the coil.", "correct": true}, {"id": "c", "text": "strongest outside the coil.", "correct": false}]'::jsonb, '{B1,B2}'),
