    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The symbol for flux density is', '[{"id": "a", "text": "H (capital).", "correct": false}, {"id": "b", "text": "Φ (phi).", "correct": false}, {"id": "c", "text": "B (capital).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A paramagnetic material has a relative permeability of', '[{"id": "a", "text": "zero.", "correct": false}, {"id": "b", "text": "less than unity.", "correct": false}, {"id": "c", "text": "greater than unity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Through which material will magnetic lines of force pass the most readily?', '[{"id": "a", "text": "Copper.", "correct": false}, {"id": "b", "text": "Iron.", "correct": true}, {"id": "c", "text": "Aluminium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Permanent magnets have', '[{"id": "a", "text": "high reluctance, high coercive force.", "correct": true}, {"id": "b", "text": "low reluctance, high coercive force.", "correct": false}, {"id": "c", "text": "high reluctance, low coercive force.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The term used to denote the strength of a magnetic field is', '[{"id": "a", "text": "retentivity.", "correct": false}, {"id": "b", "text": "hysteresis.", "correct": false}, {"id": "c", "text": "flux density.", "correct": true}]'::jsonb, '{B1,B2}'),
