    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A non-magnetic metal', '[{"id": "a", "text": "has high retentivity.", "correct": false}, {"id": "b", "text": "has no permeability.", "correct": true}, {"id": "c", "text": "is a poor conductor.", "correct": false}]'::jsonb, '{B1,B2}'),
