    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Storage of magnets should be', '[{"id": "a", "text": "in a non magnetic pox.", "correct": false}, {"id": "b", "text": "in pairs with keeper plates.", "correct": true}, {"id": "c", "text": "in pairs end to end.", "correct": false}]'::jsonb, '{B1,B2}'),
