    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a bar magnet is cut in half', '[{"id": "a", "text": "the magnet is destroyed.", "correct": false}, {"id": "b", "text": "two bar magnets are formed.", "correct": true}, {"id": "c", "text": "one bar magnet and one non-magnet is formed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Copper is a', '[{"id": "a", "text": "ferromagnetic material.", "correct": false}, {"id": "b", "text": "paramagnetic materials.", "correct": false}, {"id": "c", "text": "diamagnetic material.", "correct": true}]'::jsonb, '{B1,B2}'),
