    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An example of a paramagnetic material is', '[{"id": "a", "text": "silver.", "correct": false}, {"id": "b", "text": "iron.", "correct": false}, {"id": "c", "text": "glass.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Vibration in a magnet causes', '[{"id": "a", "text": "flux to stay the same.", "correct": false}, {"id": "b", "text": "flux to decrease.", "correct": true}, {"id": "c", "text": "flux to increase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Permeability of a material can be found by', '[{"id": "a", "text": "flux density / MMF.", "correct": true}, {"id": "b", "text": "MMF * flux density.", "correct": false}, {"id": "c", "text": "MMF / flux density.", "correct": false}]'::jsonb, '{B1,B2}'),
