    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If cobalt has a permeability of 4800 it is a', '[{"id": "a", "text": "ferromagnetic.", "correct": true}, {"id": "b", "text": "paramagnetic.", "correct": false}, {"id": "c", "text": "diamagnetic.", "correct": false}]'::jsonb, '{B1,B2}'),
