    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Magnetic flux', '[{"id": "a", "text": "exist in all space around the magnet.", "correct": true}, {"id": "b", "text": "is more concentrated at the centre of bar magnet.", "correct": false}, {"id": "c", "text": "occupies the space around the magnet with equal flux density.", "correct": false}]'::jsonb, '{B1,B2}'),
