    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Spontaneous magnetism is associated with', '[{"id": "a", "text": "diamagnetic materials.", "correct": false}, {"id": "b", "text": "ferromagnetic materials.", "correct": true}, {"id": "c", "text": "paramagnetic materials.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two inductive coils are placed in close proximity with each other at 90 degrees. The number of flux linkages is', '[{"id": "a", "text": "0.", "correct": true}, {"id": "b", "text": "maximum negative.", "correct": false}, {"id": "c", "text": "maximum positive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the mutual inductance if two coils of 10 mH and 500 mH have 90% of the flux transferred from one to the other?', '[{"id": "a", "text": "459 mH.", "correct": false}, {"id": "b", "text": "5 mH.", "correct": false}, {"id": "c", "text": "63 mH.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An inductor has 1,000 turns of wire and a cross sectional area of 0.001 m². If the core has a permeability of 0.000,001 and the coil is 0.1m. What is the value of the inductor?', '[{"id": "a", "text": "100 µH.", "correct": false}, {"id": "b", "text": "100 mH.", "correct": false}, {"id": "c", "text": "10 mH.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Three inductors 10 mH, 5 mH and 20 mH are connected in parallel. What is the total inductance?', '[{"id": "a", "text": "Without knowing the coupling factor the total inductance cannot be found.", "correct": false}, {"id": "b", "text": "2.86 mH.", "correct": true}, {"id": "c", "text": "1.35 mH.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the current reaches a maximum through an inductor of 2 A in 15 seconds, what is the current after 3 seconds?', '[{"id": "a", "text": "1.26A.", "correct": true}, {"id": "b", "text": "0.63A.", "correct": false}, {"id": "c", "text": "1A.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The time constant of an inductor is', '[{"id": "a", "text": "LR", "correct": false}, {"id": "b", "text": "L/R.", "correct": true}, {"id": "c", "text": "L^2/R.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the rate of change of current is halved, mutual inductance will', '[{"id": "a", "text": "stay the same.", "correct": true}, {"id": "b", "text": "halve.", "correct": false}, {"id": "c", "text": "double.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Why are the iron cores of most induction coils laminated?', '[{"id": "a", "text": "To reduce the effects of eddy currents.", "correct": true}, {"id": "b", "text": "To reduce the core reluctance.", "correct": false}, {"id": "c", "text": "To increase the core permeability.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When more than two inductors of different inductance are connected in parallel in a circuit, the total inductance is', '[{"id": "a", "text": "equal to the sum of the individual inductance.", "correct": false}, {"id": "b", "text": "equal to the inductance of the highest rated inductor.", "correct": false}, {"id": "c", "text": "less than the inductance of the lowest rated inductor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An AC inductive circuit has an inductance of 10 mH and a frequency input of 1000 Hz. The opposition to current flow is approximately', '[{"id": "a", "text": "63,000 ohms.", "correct": false}, {"id": "b", "text": "63 ohms.", "correct": true}, {"id": "c", "text": "630 ohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An inductor of resistance 5 kΩ and inductance 2 mH is connected to a DC circuit. The time constant is', '[{"id": "a", "text": "400 ns.", "correct": true}, {"id": "b", "text": "10 seconds.", "correct": false}, {"id": "c", "text": "40 ms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When switching off the supply, the back EMF in a collapsing field in an inductor', '[{"id": "a", "text": "can be multiple times bigger than forward EMF.", "correct": true}, {"id": "b", "text": "never exceeds forward EMF.", "correct": false}, {"id": "c", "text": "is equal to forward EMF.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An induced current in a coil', '[{"id": "a", "text": "opposes the EMF producing it.", "correct": true}, {"id": "b", "text": "does not affect the EMF producing it.", "correct": false}, {"id": "c", "text": "aids the EMF producing it.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), '1 Volt is produced when a current of 1 Amp per second is varied in a coil. This is a definition of', '[{"id": "a", "text": "1 Ampere per metre.", "correct": false}, {"id": "b", "text": "1 Henry.", "correct": true}, {"id": "c", "text": "1 Coulomb per second.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two inductor coils in very close proximity, if one of the coils is rotated 90 degrees slowly away from the other the mutual inductance', '[{"id": "a", "text": "decreases.", "correct": true}, {"id": "b", "text": "remains the same.", "correct": false}, {"id": "c", "text": "increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An inductor is said to be saturated when', '[{"id": "a", "text": "the current is at a maximum.", "correct": false}, {"id": "b", "text": "the current through it is zero.", "correct": false}, {"id": "c", "text": "it will no longer accept lines of flux.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a DC motor, the stator’s magnetic field, due to armature reaction, moves', '[{"id": "a", "text": "in the same direction of rotation of the armature.", "correct": false}, {"id": "b", "text": "in the opposite direction of rotation of the armature.", "correct": true}, {"id": "c", "text": "into alignment with the GNA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A small air gap between magnetic poles results', '[{"id": "a", "text": "in a weaker field than a large air gap, for the same magnetising force.", "correct": false}, {"id": "b", "text": "in a stronger field than a large air gap, for the same magnetising force.", "correct": true}, {"id": "c", "text": "in the same field as a large air gap, for the same magnetising force.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The electromagnetic brake coil in an actuator would be energised', '[{"id": "a", "text": "only at the instant of starting and stopping.", "correct": false}, {"id": "b", "text": "all the time in flight.", "correct": false}, {"id": "c", "text": "only when the actuator is running.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a shunt wound direct current motor with a constant voltage field supply, the torque developed by the motor is', '[{"id": "a", "text": "independent of load.", "correct": false}, {"id": "b", "text": "directly proportional to armature current.", "correct": true}, {"id": "c", "text": "inversely proportional to the armature current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Decreasing the field current in a shunt motor will', '[{"id": "a", "text": "decrease speed and increase torque.", "correct": false}, {"id": "b", "text": "increase speed and increase torque.", "correct": false}, {"id": "c", "text": "increase speed and decrease torque.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To calculate generator output you need to know the', '[{"id": "a", "text": "armature speed and number of series conductors.", "correct": false}, {"id": "b", "text": "armature speed and field strength.", "correct": true}, {"id": "c", "text": "armature speed and number of parallel conductors.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a shunt motor, if you reverse both field current and the armature current, the motor will', '[{"id": "a", "text": "stop.", "correct": false}, {"id": "b", "text": "change direction.", "correct": false}, {"id": "c", "text": "continue to run in the same direction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A starter generator has a', '[{"id": "a", "text": "low resistance series field and a low resistance shunt field.", "correct": false}, {"id": "b", "text": "low resistance series field and a high resistance shunt field.", "correct": true}, {"id": "c", "text": "high resistance series field and a low resistance shunt field.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the brake coil on an actuator motor goes open circuit, the actuator will', '[{"id": "a", "text": "run slower.", "correct": false}, {"id": "b", "text": "stop.", "correct": true}, {"id": "c", "text": "over-ride its mechanical stops.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a generator speed is halved and the field strength is doubled, the voltage output will be', '[{"id": "a", "text": "unchanged.", "correct": true}, {"id": "b", "text": "doubled.", "correct": false}, {"id": "c", "text": "halved.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'How can the direction of rotation of a DC electric motor be changed?', '[{"id": "a", "text": "Reverse the electrical connections to either the field or armature windings.", "correct": true}, {"id": "b", "text": "Rotate the positive brush one commutator segment.", "correct": false}, {"id": "c", "text": "Interchange the wires which connect the motor to the external power source.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The only practical method of maintaining a constant voltage output from an aircraft generator under varying conditions of speed and load is to vary the', '[{"id": "a", "text": "speed at which the armature rotates.", "correct": false}, {"id": "b", "text": "strength of the magnetic field.", "correct": true}, {"id": "c", "text": "number of conductors in the armature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Electric motors are often classified according to the method of connecting the field coils and armature Aircraft engine starter motors are generally of which type?', '[{"id": "a", "text": "Compound.", "correct": false}, {"id": "b", "text": "Shunt (parallel).", "correct": false}, {"id": "c", "text": "Series.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a heavy mechanical load is removed from a series motor', '[{"id": "a", "text": "the speed will increase and the armature current will increase.", "correct": false}, {"id": "b", "text": "the speed will increase and the armature current will decrease.", "correct": true}, {"id": "c", "text": "the speed will decrease and the armature current will decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the correct supply were connected to a DC shunt motor which had lost its residual magnetism it would', '[{"id": "a", "text": "run in the reverse direction.", "correct": false}, {"id": "b", "text": "fail to run.", "correct": false}, {"id": "c", "text": "run normally.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'One purpose of a growler test is to determine the presence of:', '[{"id": "a", "text": "a shorted armature.", "correct": true}, {"id": "b", "text": "a broken field lead.", "correct": false}, {"id": "c", "text": "an out-of-round commutator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The purpose of an end-travel microswitch in a linear actuator is to', '[{"id": "a", "text": "remain open and closes at end travel only.", "correct": false}, {"id": "b", "text": "remain open during normal operation and only close if the actuator overruns its stops.", "correct": false}, {"id": "c", "text": "remain closed and opens at end travel only.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Linear actuators used in aircraft are of', '[{"id": "a", "text": "split field series wound type.", "correct": true}, {"id": "b", "text": "compound wound type.", "correct": false}, {"id": "c", "text": "split field shunt wound type.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a generator sparks, a possible reason is', '[{"id": "a", "text": "the brush springs are loose.", "correct": true}, {"id": "b", "text": "magnetic flux deflecting the EMF.", "correct": false}, {"id": "c", "text": "the brushes have been placed around the magnetic coil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the field strength of a generator is doubled, and the speed is doubled, the output EMF will', '[{"id": "a", "text": "stay the same.", "correct": false}, {"id": "b", "text": "double.", "correct": false}, {"id": "c", "text": "quadruple.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a DC motor the pole pairs are', '[{"id": "a", "text": "connected to the brush gear.", "correct": false}, {"id": "b", "text": "part of the armature.", "correct": false}, {"id": "c", "text": "embedded within the field coils.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A series wound DC motor, the field has', '[{"id": "a", "text": "few turns of thin wire.", "correct": false}, {"id": "b", "text": "many turns of thin wire.", "correct": false}, {"id": "c", "text": "few turns of thick wire.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Doubling the running time of an electrical machine would', '[{"id": "a", "text": "double the current used.", "correct": false}, {"id": "b", "text": "double the joules used.", "correct": true}, {"id": "c", "text": "double the watts used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'On a linear actuator, the field cutoff coil will be energized when', '[{"id": "a", "text": "only as the actuator commences movement.", "correct": false}, {"id": "b", "text": "the actuator is not running.", "correct": true}, {"id": "c", "text": "the actuator is running.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An electric motor produces a force of 5 N at a distance of 0.2m from the centre of rotation and rotates at a speed of 100 revs/sec. The motors output is', '[{"id": "a", "text": "100 horsepower.", "correct": false}, {"id": "b", "text": "628.4 watts.", "correct": true}, {"id": "c", "text": "314.2 watts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Starter motors are usually', '[{"id": "a", "text": "series wound.", "correct": true}, {"id": "b", "text": "compound wound.", "correct": false}, {"id": "c", "text": "shunt wound.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Generator brushes are normally made of', '[{"id": "a", "text": "steel.", "correct": false}, {"id": "b", "text": "carbon.", "correct": true}, {"id": "c", "text": "brass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'As the generator load is increased (within its rated capacity), the voltage will', '[{"id": "a", "text": "remain constant and the amperage output will decrease.", "correct": false}, {"id": "b", "text": "decrease and the amperage output will increase.", "correct": false}, {"id": "c", "text": "remain constant and the amperage output will increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The voltage output of a generator is controlled by', '[{"id": "a", "text": "varying the current of the output.", "correct": false}, {"id": "b", "text": "varying the resistance of the output.", "correct": false}, {"id": "c", "text": "varying the current of the field.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The current flowing in the armature of a DC motor is equal to', '[{"id": "a", "text": "(applied volts-generated volts) / armature resistance.", "correct": true}, {"id": "b", "text": "(applied volts-generated volts) * armature resistance.", "correct": false}, {"id": "c", "text": "applied volts + generated volts / armature resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What device is used to convert alternating current, which has been induced into the loops of the rotating armature of a DC generator into direct current as it leaves the generator?', '[{"id": "a", "text": "An inverter.", "correct": false}, {"id": "b", "text": "A commutator.", "correct": true}, {"id": "c", "text": "A rectifier.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which of the following is not one of the purposes of interpoles in a generator?', '[{"id": "a", "text": "Overcome armature reaction.", "correct": false}, {"id": "b", "text": "Reduce arcing at the brushes.", "correct": false}, {"id": "c", "text": "Reduce field strength.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To reverse the direction of a series motor', '[{"id": "a", "text": "the direction of the current through the field and the armature is reversed.", "correct": false}, {"id": "b", "text": "the direction of the current through the field is reversed.", "correct": true}, {"id": "c", "text": "a second series field is fitted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The current consumed by a DC starter motor will', '[{"id": "a", "text": "remain relatively constant over the starting speed range.", "correct": false}, {"id": "b", "text": "decrease as the engine speed increases.", "correct": true}, {"id": "c", "text": "increase as the engine speed increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'How are generators rated?', '[{"id": "a", "text": "Impedance at rated voltage.", "correct": false}, {"id": "b", "text": "Amperes at rated voltage.", "correct": true}, {"id": "c", "text": "Watts at rated voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Due to armature reaction in a DC motor', '[{"id": "a", "text": "the leading pole tips are magnetically weakened.", "correct": false}, {"id": "b", "text": "the trailing pole tips are magnetically weakened.", "correct": true}, {"id": "c", "text": "the magnetic flux is restored by moving the MNA towards the GNA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Some electric motors have two sets of field winding wound in opposite directions so that the', '[{"id": "a", "text": "speed of the motor can be more closely controlled.", "correct": false}, {"id": "b", "text": "motor can be operated in either direction.", "correct": true}, {"id": "c", "text": "power output of the motor can be more closely controlled.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What polarity do interpoles take in a DC motor?', '[{"id": "a", "text": "Either, provided they lay on the MNA.", "correct": false}, {"id": "b", "text": "The same as the next main pole ahead in the direction of rotation.", "correct": false}, {"id": "c", "text": "The same as the next main pole behind in the direction of rotation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the principal advantage of the series-wound DC motor?', '[{"id": "a", "text": "Suitable for constant speed use.", "correct": false}, {"id": "b", "text": "High starting torque.", "correct": true}, {"id": "c", "text": "Low starting torque.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Interpole windings fitted to DC series wound generators are', '[{"id": "a", "text": "in series with the armature.", "correct": true}, {"id": "b", "text": "in series with the field.", "correct": false}, {"id": "c", "text": "in parallel with the armature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What polarity do interpoles take in a DC generator?', '[{"id": "a", "text": "The same as the next main pole behind in the direction of rotation.", "correct": false}, {"id": "b", "text": "Either, providing they lay on M.N.A.", "correct": false}, {"id": "c", "text": "The same as the next main pole ahead in the direction of rotation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The method most often used in overcoming the effect of armature reaction is through the use of', '[{"id": "a", "text": "shaded poles.", "correct": false}, {"id": "b", "text": "interpoles.", "correct": true}, {"id": "c", "text": "drum-wound armatures in combination with a negatively connected series field.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The starting current of a series-wound DC motor, in passing through both the field and armature windings produces a', '[{"id": "a", "text": "speed slightly higher when unloaded.", "correct": false}, {"id": "b", "text": "high starting torque.", "correct": true}, {"id": "c", "text": "low starting torque.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To increase the speed of a shunt motor a resistance is placed', '[{"id": "a", "text": "in parallel with the field.", "correct": false}, {"id": "b", "text": "in series with the field.", "correct": true}, {"id": "c", "text": "in series with the armature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 200 volt motor is taking 10 amperes armature current, the armature resistance is 0.1 ohm. The Back- EMF under these conditions will be', '[{"id": "a", "text": "201 volts.", "correct": false}, {"id": "b", "text": "199 volts.", "correct": true}, {"id": "c", "text": "1 volt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is a method used for restoring generator field residual magnetism?', '[{"id": "a", "text": "Energize the armature.", "correct": false}, {"id": "b", "text": "Flash the fields.", "correct": true}, {"id": "c", "text": "Reseat the brushes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A high surge of current is required when a DC electric motor is first started. As the speed of the motor increase', '[{"id": "a", "text": "the counter emf decreases proportionally.", "correct": false}, {"id": "b", "text": "the applied emf increases proportionally.", "correct": false}, {"id": "c", "text": "the counter emf builds up and opposes the applied emf, thus reducing the current flow through the", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Aircraft generators are cooled by', '[{"id": "a", "text": "fuel cooling radiators.", "correct": false}, {"id": "b", "text": "oil cooling radiators around the main body.", "correct": false}, {"id": "c", "text": "ram air.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'On a combined DC starter - generator system', '[{"id": "a", "text": "the voltage regulator is connected to the shunt field after the start cycle is completed.", "correct": true}, {"id": "b", "text": "the voltage regulator controls the start sequence during engine starting.", "correct": false}, {"id": "c", "text": "the series coil is open circuit during the engine start sequence.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the field current to a shunt wound DC motor is decreased when operating at a constant load, the motor speed will', '[{"id": "a", "text": "reduce.", "correct": false}, {"id": "b", "text": "not change.", "correct": false}, {"id": "c", "text": "increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a motor is spinning at 50 cycles per second, how long is 1 cycle of the output?', '[{"id": "a", "text": "50 seconds.", "correct": false}, {"id": "b", "text": "0.83 seconds.", "correct": false}, {"id": "c", "text": "0.02 seconds.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a an DC motor, the rotation of the MNA', '[{"id": "a", "text": "is opposite to the rotation of the armature.", "correct": true}, {"id": "b", "text": "is slightly less speed than the rotation of the armature.", "correct": false}, {"id": "c", "text": "is the same as the rotation of the armature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a wave wound generator with 4 poles, what would be the minimum number of brushes?', '[{"id": "a", "text": "4.", "correct": false}, {"id": "b", "text": "2.", "correct": true}, {"id": "c", "text": "8.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A wire is rotated through a magnetic field. To give DC it must be connected to', '[{"id": "a", "text": "a commutator.", "correct": true}, {"id": "b", "text": "slip rings.", "correct": false}, {"id": "c", "text": "a rectifier.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the supply to a DC shunt motor was reversed', '[{"id": "a", "text": "it would rotate in the same direction.", "correct": true}, {"id": "b", "text": "it would fail to run.", "correct": false}, {"id": "c", "text": "it would rotate in the opposite direction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A series motor draws a high current on start, and then the current reduces. This is due to', '[{"id": "a", "text": "the resistance of the field and the armature in series.", "correct": false}, {"id": "b", "text": "the resistance of the field and armature in parallel.", "correct": false}, {"id": "c", "text": "the back EMF.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Interpoles in a DC generator are connected', '[{"id": "a", "text": "in series with the armature.", "correct": true}, {"id": "b", "text": "in series with the field.", "correct": false}, {"id": "c", "text": "in parallel with the armature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a DC generator, the effect of armature reaction may be reduced by moving the brush gear', '[{"id": "a", "text": "in the direction of armature rotation towards the MNA.", "correct": true}, {"id": "b", "text": "from MNA to GNA.", "correct": false}, {"id": "c", "text": "against the direction of armature rotation towards the MNA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The windings embedded in the pole faces of a DC generator are', '[{"id": "a", "text": "commutating coils.", "correct": false}, {"id": "b", "text": "interpoles.", "correct": false}, {"id": "c", "text": "compensating windings.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 6 pole wave-wound generator has', '[{"id": "a", "text": "3 brushes.", "correct": false}, {"id": "b", "text": "2 brushes.", "correct": true}, {"id": "c", "text": "6 brushes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Armature reaction in a DC generator causes', '[{"id": "a", "text": "MNA to move in the opposite direction of rotation.", "correct": false}, {"id": "b", "text": "MNA to move in the direction of rotation.", "correct": true}, {"id": "c", "text": "GNA to move in the direction of rotation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a DC motor, back-EMF rises if the motor', '[{"id": "a", "text": "speed falls.", "correct": false}, {"id": "b", "text": "speed faload rises.", "correct": false}, {"id": "c", "text": "speed rises.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A DC generator armature has 6 poles and is lap wound. The number of brushes required are', '[{"id": "a", "text": "2.", "correct": false}, {"id": "b", "text": "3.", "correct": false}, {"id": "c", "text": "6.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Reactive sparking is reduced by', '[{"id": "a", "text": "interpoles.", "correct": true}, {"id": "b", "text": "compensating windings.", "correct": false}, {"id": "c", "text": "auxiliary windings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The back-EMF in a DC motor is', '[{"id": "a", "text": "equal to the applied EMF.", "correct": false}, {"id": "b", "text": "less than the applied EMF.", "correct": true}, {"id": "c", "text": "greater than the applied EMF.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The flux density of a magnetic field is 1.5T. The length of the conductor in the field is 2 m and the current flowing through the conductor is 5 amps. The force on the conductor is', '[{"id": "a", "text": "6 Newtons.", "correct": false}, {"id": "b", "text": "15 Newtons.", "correct": true}, {"id": "c", "text": "75 Newtons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A DC shunt motor has 28 volts applied. The current taken from the armature of 2 ohms resistance is 1 amp The Back-EMF is', '[{"id": "a", "text": "26 V.", "correct": true}, {"id": "b", "text": "30 V.", "correct": false}, {"id": "c", "text": "27 V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a motor, armature reaction causes the MNA to move', '[{"id": "a", "text": "against the direction of rotation.", "correct": true}, {"id": "b", "text": "in the direction of rotation.", "correct": false}, {"id": "c", "text": "to the GNA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a generator system, a stabilizing winding is used', '[{"id": "a", "text": "in series with the field to prevent oscillations.", "correct": true}, {"id": "b", "text": "to control output current.", "correct": false}, {"id": "c", "text": "to prevent voltage overshoot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What part of a DC motor would you find the poles?', '[{"id": "a", "text": "Brushes.", "correct": false}, {"id": "b", "text": "Rotor.", "correct": false}, {"id": "c", "text": "Stator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An A.C. shunt wound motor sometimes uses a volts dropping resistor. The resistor would be', '[{"id": "a", "text": "in series with the field.", "correct": true}, {"id": "b", "text": "in series with the supply.", "correct": false}, {"id": "c", "text": "in series with the armature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Commutator ripple can be reduced by', '[{"id": "a", "text": "increasing generator frequency.", "correct": false}, {"id": "b", "text": "the use of a ripple filter.", "correct": true}, {"id": "c", "text": "a resistor in series with the armature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a DC motor the interpoles are part of the', '[{"id": "a", "text": "rotor assembly.", "correct": false}, {"id": "b", "text": "stator assembly.", "correct": true}, {"id": "c", "text": "field.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Armature reaction is', '[{"id": "a", "text": "the MMF opposing rotation.", "correct": true}, {"id": "b", "text": "due to dirty or worn commutator.", "correct": false}, {"id": "c", "text": "reactive sparking.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A shunt motor', '[{"id": "a", "text": "is constant speed.", "correct": true}, {"id": "b", "text": "has high starting torque.", "correct": false}, {"id": "c", "text": "gives constant torque with variations in speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a DC shunt motor, if the field resistance is increased what happens to the back EMF?', '[{"id": "a", "text": "Decreases.", "correct": true}, {"id": "b", "text": "Remains the same.", "correct": false}, {"id": "c", "text": "Increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To increase the voltage output of a generator you can', '[{"id": "a", "text": "decrease speed.", "correct": false}, {"id": "b", "text": "It is not speed dependant.", "correct": false}, {"id": "c", "text": "increase speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Generator voltage is', '[{"id": "a", "text": "dependant on speed of rotation.", "correct": true}, {"id": "b", "text": "independent of speed of rotation.", "correct": false}, {"id": "c", "text": "not dependant on speed of rotation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The output from a generator to a commutator is', '[{"id": "a", "text": "pulsed DC.", "correct": false}, {"id": "b", "text": "DC.", "correct": false}, {"id": "c", "text": "AC.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the main disadvantage of a starter generator?', '[{"id": "a", "text": "Heavier than like for like.", "correct": false}, {"id": "b", "text": "Will not supply output at low rpm.", "correct": true}, {"id": "c", "text": "Can only be used on piston engines.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Back-EMF is the greatest when a motor is', '[{"id": "a", "text": "at operating speed.", "correct": true}, {"id": "b", "text": "under heavy load.", "correct": false}, {"id": "c", "text": "just starting to rotate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When a conductor carrying a current and placed in a magnetic field it experiences', '[{"id": "a", "text": "an electrostatic force.", "correct": false}, {"id": "b", "text": "an electromagnetic force.", "correct": true}, {"id": "c", "text": "a magnetic force.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The type of motor used in a linear actuator is', '[{"id": "a", "text": "parallel (shunt wound).", "correct": false}, {"id": "b", "text": "compound.", "correct": false}, {"id": "c", "text": "series.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the speed of a coil in a magnetic field is doubled and the field strength is doubled the output will', '[{"id": "a", "text": "quadruple.", "correct": true}, {"id": "b", "text": "stay the same.", "correct": false}, {"id": "c", "text": "halve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'How many brushes are used in an 8 pole wave wound machine', '[{"id": "a", "text": "6.", "correct": false}, {"id": "b", "text": "8.", "correct": false}, {"id": "c", "text": "2.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In the shunt generator the field is supplied by', '[{"id": "a", "text": "the load.", "correct": false}, {"id": "b", "text": "the armature.", "correct": true}, {"id": "c", "text": "a separate supply.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Increasing the speed of an aircraft generator results in an automatic', '[{"id": "a", "text": "field circuit resistance decrease.", "correct": false}, {"id": "b", "text": "armature circuit resistance increase.", "correct": false}, {"id": "c", "text": "field circuit resistance increase.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which generators are usually used on aircraft?', '[{"id": "a", "text": "Shunt.", "correct": true}, {"id": "b", "text": "Compound.", "correct": false}, {"id": "c", "text": "Series.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a cumulative compound wound generator the', '[{"id": "a", "text": "the series and shunt fields assist each other.", "correct": true}, {"id": "b", "text": "the series and shunt fields oppose each other.", "correct": false}, {"id": "c", "text": "the voltage falls suddenly with an increase in load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The shunt wound generator is controlled by a variable resistance in', '[{"id": "a", "text": "parallel with the field.", "correct": false}, {"id": "b", "text": "series with the armature.", "correct": false}, {"id": "c", "text": "series with the field.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The series wound generator’s terminal voltage will, when below saturation', '[{"id": "a", "text": "increase with an increase in load.", "correct": true}, {"id": "b", "text": "decrease with an increase in load.", "correct": false}, {"id": "c", "text": "decrease with a decrease in rotational speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The shunt wound generator is normally started', '[{"id": "a", "text": "on load.", "correct": false}, {"id": "b", "text": "Either of the above.", "correct": false}, {"id": "c", "text": "off load.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Armature reaction in a DC motor causes the neutral axis to shift in', '[{"id": "a", "text": "the direction in the direction of armature rotation.", "correct": false}, {"id": "b", "text": "the direction opposite to the direction of armature rotation.", "correct": true}, {"id": "c", "text": "either direction depending on current flow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An indication of good commutation on a DC machine would be', '[{"id": "a", "text": "high armature currents.", "correct": false}, {"id": "b", "text": "little or no sparking at the commutator.", "correct": true}, {"id": "c", "text": "silent operation of the machine.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If compound DC generators are operated in parallel they must', '[{"id": "a", "text": "all rotate at the same speed.", "correct": false}, {"id": "b", "text": "have an equalising or load sharing loop.", "correct": true}, {"id": "c", "text": "all use the same voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The windings embedded in the pole faces of a generator are', '[{"id": "a", "text": "commutating coils.", "correct": false}, {"id": "b", "text": "interpoles.", "correct": false}, {"id": "c", "text": "compensating coils.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Prolonged reactive sparking in a DC generator could damage the', '[{"id": "a", "text": "armature.", "correct": false}, {"id": "b", "text": "commutator.", "correct": true}, {"id": "c", "text": "pole pieces.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The poles of a DC generator are laminated to', '[{"id": "a", "text": "reduce hysteresis losses.", "correct": false}, {"id": "b", "text": "reduce flux losses.", "correct": false}, {"id": "c", "text": "reduce eddy current losses.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'One advantage of a DC motor over an AC motor is', '[{"id": "a", "text": "the direction of rotation of the rotor can be changed.", "correct": true}, {"id": "b", "text": "less voltage is required in DC than AC.", "correct": false}, {"id": "c", "text": "the DC motor will use less current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a shunt wound direct current motor the torque is', '[{"id": "a", "text": "inversely proportional to the current in the armature.", "correct": false}, {"id": "b", "text": "independent of load.", "correct": false}, {"id": "c", "text": "proportional to the current in the armature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Convention requires that in a symmetrical 3 phase system, the', '[{"id": "a", "text": "red voltage is taken as the reference phase.", "correct": true}, {"id": "b", "text": "yellow voltage phase leads the red phase by 120 degrees.", "correct": false}, {"id": "c", "text": "red voltage phase leads the blue phase by 120 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the phase difference in a circuit with 100V, drawing 0.5 amps, consuming 50 Watts?', '[{"id": "a", "text": "0°.", "correct": true}, {"id": "b", "text": "45°.", "correct": false}, {"id": "c", "text": "90°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The power factor of a circuit containing an imbalance of inductive and capacitive reactance is', '[{"id": "a", "text": "greater than unity.", "correct": false}, {"id": "b", "text": "unity.", "correct": false}, {"id": "c", "text": "less than unity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What value is the same as the equivalent D.C. heating effect?', '[{"id": "a", "text": "Peak.", "correct": false}, {"id": "b", "text": "Average.", "correct": false}, {"id": "c", "text": "Root Mean Square.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What shape is the waveform when the input pulse and the time base are unequal?', '[{"id": "a", "text": "Saw tooth.", "correct": false}, {"id": "b", "text": "Square.", "correct": false}, {"id": "c", "text": "Rectangular.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A sine wave has 5 amps RMS value. What is the peak value?', '[{"id": "a", "text": "7.07 amps.", "correct": true}, {"id": "b", "text": "6.37 amps.", "correct": false}, {"id": "c", "text": "10 amps.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the wave shape of the x-axis input of a traversing oscilloscope image?', '[{"id": "a", "text": "Rectangular.", "correct": false}, {"id": "b", "text": "Triangular.", "correct": true}, {"id": "c", "text": "Square.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a purely resistive AC circuit, the current vector is', '[{"id": "a", "text": "+90° out of phase with the voltage vector.", "correct": false}, {"id": "b", "text": "in phase with the voltage vector.", "correct": true}, {"id": "c", "text": "-90° out of phase with the voltage vector.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When comparing the average values of an AC generator output, to the peak values', '[{"id": "a", "text": "average voltage = 0.707 * peak voltage.", "correct": false}, {"id": "b", "text": "average voltage = 0.63 * peak voltage.", "correct": true}, {"id": "c", "text": "average voltage = same as the peak voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A parallel circuit at resonance has', '[{"id": "a", "text": "maximum impedance.", "correct": true}, {"id": "b", "text": "zero impedance.", "correct": false}, {"id": "c", "text": "minimum impedance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 10 ohm resistor has a 14.14 V peak drop across it. What power is dissipated?', '[{"id": "a", "text": "19.99 W.", "correct": false}, {"id": "b", "text": "10 W.", "correct": true}, {"id": "c", "text": "1.414 W.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a 1 ohm circuit produces a 50 W output, the phase angle is', '[{"id": "a", "text": "45°.", "correct": false}, {"id": "b", "text": "0°.", "correct": true}, {"id": "c", "text": "90°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What does a rectifier do?', '[{"id": "a", "text": "Changes alternating current into direct current.", "correct": true}, {"id": "b", "text": "Reduces voltage.", "correct": false}, {"id": "c", "text": "Changes direct current into alternating current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The ratio between apparent power and true power is the', '[{"id": "a", "text": "power rating.", "correct": false}, {"id": "b", "text": "power factor.", "correct": true}, {"id": "c", "text": "efficiency.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Unless otherwise specified, any values given for current or voltage in an AC circuit are assumed to be', '[{"id": "a", "text": "effective values.", "correct": true}, {"id": "b", "text": "instantaneous values.", "correct": false}, {"id": "c", "text": "maximum values.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which aircraft circuit would be most likely to use frequency wild 200 V AC?', '[{"id": "a", "text": "Hydraulic pump.", "correct": false}, {"id": "b", "text": "Windscreen heating.", "correct": true}, {"id": "c", "text": "Standby compass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In an AC circuit how is the value of true power calculated?', '[{"id": "a", "text": "By voltmeter readings multiplied by ammeter readings.", "correct": false}, {"id": "b", "text": "By volts multiplied by amps multiplied by power factor.", "correct": true}, {"id": "c", "text": "By watt meter readings multiplied by power factor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'One of the chief advantages of alternating current is that it can be transmitted at a high voltage with a low power loss, the voltage can then be changed to any desired value of', '[{"id": "a", "text": "DC by means of transformers.", "correct": false}, {"id": "b", "text": "DC by means of inverters.", "correct": false}, {"id": "c", "text": "AC by means of transformers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'How many amperes will a 28-volt generator be required to supply to a circuit containing five lamps in parallel, three of which have a resistance of 6 ohms each and two of which have a resistance of 5 ohms each?', '[{"id": "a", "text": "1 ampere.", "correct": false}, {"id": "b", "text": "25.23 amperes.", "correct": true}, {"id": "c", "text": "1.11 amperes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Frequency (Hz) is the number of cycles per', '[{"id": "a", "text": "minute.", "correct": false}, {"id": "b", "text": "second.", "correct": true}, {"id": "c", "text": "revolution.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The frequency of a power wave in an AC resistance circuit is', '[{"id": "a", "text": "half the frequency for voltage and current.", "correct": false}, {"id": "b", "text": "the same as the frequency for voltage and current.", "correct": false}, {"id": "c", "text": "twice the frequency for voltage and current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In an AC circuit, the effective voltage is', '[{"id": "a", "text": "less than the maximum instantaneous voltage.", "correct": true}, {"id": "b", "text": "equal to the maximum instantaneous voltage.", "correct": false}, {"id": "c", "text": "greater than the maximum instantaneous voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which wave form is stepped positive and negative with unequal length sides?', '[{"id": "a", "text": "Rectangular wave.", "correct": true}, {"id": "b", "text": "Trapezoidal wave.", "correct": false}, {"id": "c", "text": "Saw tooth wave.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The value of an AC sine wave that will give an equivalent heating effect in a DC resistor is the', '[{"id": "a", "text": "peak value.", "correct": false}, {"id": "b", "text": "RMS value.", "correct": true}, {"id": "c", "text": "average value.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The peak factor for a sine wave is', '[{"id": "a", "text": "1.1", "correct": false}, {"id": "b", "text": "0.707.", "correct": false}, {"id": "c", "text": "1.414.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An integrated step input at unequal time base produces', '[{"id": "a", "text": "a saw tooth wave.", "correct": true}, {"id": "b", "text": "a square wave.", "correct": false}, {"id": "c", "text": "a sine wave.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A sine wave of RMS value 7.07 volts has a peak to peak value of', '[{"id": "a", "text": "20 volts.", "correct": true}, {"id": "b", "text": "10 volts.", "correct": false}, {"id": "c", "text": "0.707 volts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The true power in an AC circuit is given by', '[{"id": "a", "text": "volts * amps.", "correct": false}, {"id": "b", "text": "PF * volts * amps.", "correct": true}, {"id": "c", "text": "voltmeter reading * PF.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The average value of 100 volts peak AC is', '[{"id": "a", "text": "70.7 volts.", "correct": false}, {"id": "b", "text": "141. 4 volts.", "correct": false}, {"id": "c", "text": "63.7 volts.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The RMS value of 200 volts peak to peak is', '[{"id": "a", "text": "127.4 volts.", "correct": false}, {"id": "b", "text": "70.7 volts.", "correct": true}, {"id": "c", "text": "141.4 volts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The power factor of an AC circuit is the', '[{"id": "a", "text": "cosine of the phase angle.", "correct": true}, {"id": "b", "text": "tangent of the phase angle.", "correct": false}, {"id": "c", "text": "sine of the phase angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The Form Factor of an AC waveform can be found by', '[{"id": "a", "text": "RMS value divided by the average value.", "correct": true}, {"id": "b", "text": "average value divided by the RMS value.", "correct": false}, {"id": "c", "text": "average value times the RMS value.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A differentiator has a time constant which is', '[{"id": "a", "text": "long.", "correct": false}, {"id": "b", "text": "equal to the input pulse.", "correct": false}, {"id": "c", "text": "short.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the frequency is increased in an AC circuit of pure resistance, the effect is', '[{"id": "a", "text": "nothing.", "correct": true}, {"id": "b", "text": "decreased resistance.", "correct": false}, {"id": "c", "text": "increased resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What sort of wave would be used in a CR oscilloscope to control sweep?', '[{"id": "a", "text": "Square.", "correct": false}, {"id": "b", "text": "Sine wave.", "correct": false}, {"id": "c", "text": "Sawtooth.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If an AC sine wave has an RMS value of 5 V its peak value is', '[{"id": "a", "text": "6.37 V.", "correct": false}, {"id": "b", "text": "7.07 V.", "correct": true}, {"id": "c", "text": "14.14 V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Apparent power in an AC circuit is found by', '[{"id": "a", "text": "V * I * cos φ.", "correct": false}, {"id": "b", "text": "V * I * sin φ.", "correct": false}, {"id": "c", "text": "V * I.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A sine wave has a periodic time of 0.5 milliseconds, what is its frequency?', '[{"id": "a", "text": "200 Hz.", "correct": false}, {"id": "b", "text": "2Khz.", "correct": true}, {"id": "c", "text": "20Khz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Phase angle is', '[{"id": "a", "text": "the cosine of the peak value of an ac voltage.", "correct": false}, {"id": "b", "text": "the difference in degrees of rotation between 2 alternating voltages or currents or a voltage and a", "correct": false}, {"id": "c", "text": "current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The impedance of an AC circuit is measured in', '[{"id": "a", "text": "ohms.", "correct": true}, {"id": "b", "text": "kilovolt-amperes.", "correct": false}, {"id": "c", "text": "amperes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What happens to the current in a series resistive resonant circuit?', '[{"id": "a", "text": "It is maximum.", "correct": true}, {"id": "b", "text": "It is minimum.", "correct": false}, {"id": "c", "text": "It is zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A circuit has 115 V RMS, 2.5 A at 60 degrees, what is the power dissipated?', '[{"id": "a", "text": "79 W.", "correct": false}, {"id": "b", "text": "300 VA.", "correct": false}, {"id": "c", "text": "143 W.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a resonant parallel circuit, current is', '[{"id": "a", "text": "zero.", "correct": false}, {"id": "b", "text": "minimum.", "correct": true}, {"id": "c", "text": "maximum.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Power factor is', '[{"id": "a", "text": "sin theta.", "correct": false}, {"id": "b", "text": "tan theta.", "correct": false}, {"id": "c", "text": "cos theta.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Peak factor in a standard AC circuit is', '[{"id": "a", "text": "1.11 times max. value of applied voltage.", "correct": false}, {"id": "b", "text": "1.414 times max. value of applied voltage.", "correct": true}, {"id": "c", "text": "0.707 time max. value of applied voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The controlling wave in a CRT is', '[{"id": "a", "text": "square.", "correct": false}, {"id": "b", "text": "sawtooth.", "correct": true}, {"id": "c", "text": "sinusoidal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A wave form having equal amplitude and time base is a', '[{"id": "a", "text": "rectangular.", "correct": false}, {"id": "b", "text": "sawtooth.", "correct": false}, {"id": "c", "text": "square waveform.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The Sine wave signals of a circular time base are', '[{"id": "a", "text": "in phase.", "correct": false}, {"id": "b", "text": "phase separated by 90°.", "correct": true}, {"id": "c", "text": "phase separated by 180°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A differentiator has a time constant that will give', '[{"id": "a", "text": "a long pulse.", "correct": false}, {"id": "b", "text": "a short pulse.", "correct": true}, {"id": "c", "text": "a continuous output.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the power factor in a purely resistive circuit?', '[{"id": "a", "text": "Equal to 1.", "correct": true}, {"id": "b", "text": "Less than 1 but greater than zero.", "correct": false}, {"id": "c", "text": "Greater than 1.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In an A.C circuit, what happens if frequency is reduced?', '[{"id": "a", "text": "Inductive elements may be damaged.", "correct": true}, {"id": "b", "text": "Capacitive elements may be damaged.", "correct": false}, {"id": "c", "text": "There will be no effect.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the relationship between the voltage and the current in an A.C circuit containing resistance and inductance?', '[{"id": "a", "text": "Current lags voltage by 90°.", "correct": false}, {"id": "b", "text": "Current lags voltage by up to 90°.", "correct": true}, {"id": "c", "text": "Current leads voltage by up to 90°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Power factor relates to', '[{"id": "a", "text": "horsepower and Watts.", "correct": false}, {"id": "b", "text": "KW and KVAR.", "correct": false}, {"id": "c", "text": "true power and apparent power.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If current lags voltage by 90°, the circuit is', '[{"id": "a", "text": "resistive.", "correct": false}, {"id": "b", "text": "capacitive.", "correct": false}, {"id": "c", "text": "inductive.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A low frequency supply', '[{"id": "a", "text": "will make the circuit operate faster due to the reduced impedance.", "correct": false}, {"id": "b", "text": "may damage inductive components.", "correct": true}, {"id": "c", "text": "will have no effect on inductive components.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a parallel R, L, C circuit, the value of the capacitor is quadrupled, then the value of the impedance would', '[{"id": "a", "text": "remain the same.", "correct": false}, {"id": "b", "text": "reduce.", "correct": true}, {"id": "c", "text": "increased.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a capacitive circuit, if the frequency is increased', '[{"id": "a", "text": "reactance remains the same.", "correct": false}, {"id": "b", "text": "impedance increases.", "correct": false}, {"id": "c", "text": "the current increases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a tuned circuit at resonance, the circuit will be', '[{"id": "a", "text": "resistive.", "correct": true}, {"id": "b", "text": "capacitive.", "correct": false}, {"id": "c", "text": "inductive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A circuit has a resistance of 50 ohms and an inductance of 0.2 Henry. If it is connected to a 200 volt 50 Hz supply the reactance will be', '[{"id": "a", "text": "6.284 ohms.", "correct": false}, {"id": "b", "text": "62.84 ohms.", "correct": true}, {"id": "c", "text": "31.42 ohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'At resonant frequency the phase difference between the voltage and current of an AC supply feeding an inductive and capacitive network is', '[{"id": "a", "text": "90 degrees.", "correct": false}, {"id": "b", "text": "0 degrees.", "correct": true}, {"id": "c", "text": "180 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An increase in which of the following factors will cause an increase in the inductive reactance of a circuit?', '[{"id": "a", "text": "Inductance and frequency.", "correct": true}, {"id": "b", "text": "Resistance and capacitive reactance.", "correct": false}, {"id": "c", "text": "Resistance and voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When a circuit with a series inductance and capacitance is at resonant frequency', '[{"id": "a", "text": "the current in the circuit decreases.", "correct": false}, {"id": "b", "text": "the impedance of the circuit is such that the voltage is in phase with the current.", "correct": true}, {"id": "c", "text": "the impedance of the circuit is such that the voltage leads the current by exactly 90 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A pure capacitor, inductor and resistor are connected in series and the voltage drops across each are 10 V and the total current flowing in the circuit is 1A. How much true power is the circuit consuming?', '[{"id": "a", "text": "30VA.", "correct": false}, {"id": "b", "text": "30W.", "correct": false}, {"id": "c", "text": "10W.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If a capacitor 1 µF and an inductor 10 mH are connected in parallel what is their approximate resonant frequency?', '[{"id": "a", "text": "1.6 kHz.", "correct": true}, {"id": "b", "text": "62 Hz.", "correct": false}, {"id": "c", "text": "3.2 MHz.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Current in an inductive circuit will', '[{"id": "a", "text": "lag voltage.", "correct": true}, {"id": "b", "text": "lead voltage.", "correct": false}, {"id": "c", "text": "be at unity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The impedance of a series tuned circuit at resonance is', '[{"id": "a", "text": "zero.", "correct": false}, {"id": "b", "text": "minimum.", "correct": true}, {"id": "c", "text": "maximum.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In an inductive resistive circuit, 1 amp flows from a supply of 100 V dissipating 50 Watts of power. The phase angle is', '[{"id": "a", "text": "60°.", "correct": true}, {"id": "b", "text": "90°.", "correct": false}, {"id": "c", "text": "45°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a series LCR circuit at resonance, R = 100 ohms, L and C are each 10 ohms. The total impedance is', '[{"id": "a", "text": "zero ohms.", "correct": false}, {"id": "b", "text": "100 ohms.", "correct": true}, {"id": "c", "text": "30 ohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a high Q parallel resonant circuit, what happens to impedance if capacitance is increased by a factor of 4?', '[{"id": "a", "text": "It increases by factor of 4.", "correct": false}, {"id": "b", "text": "It reduces by 75%.", "correct": true}, {"id": "c", "text": "It remains the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A parallel circuit at resonance has its impedance at a', '[{"id": "a", "text": "maximum.", "correct": true}, {"id": "b", "text": "zero.", "correct": false}, {"id": "c", "text": "minimum.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The formula for impedance in a series circuit is the root of', '[{"id": "a", "text": "R² + (XC − XL)²", "correct": false}, {"id": "b", "text": "R² − (XL − XC)²", "correct": false}, {"id": "c", "text": "R² + (XL − XC)²", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a parallel LCR circuit, if the capacitance is increased by 4 times, what happens to the impedance of the capacitor?', '[{"id": "a", "text": "Increases by 4 times.", "correct": false}, {"id": "b", "text": "Remains the same.", "correct": false}, {"id": "c", "text": "Decreases by 75%.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the frequency to a capacitor increases, the current through it', '[{"id": "a", "text": "decreases.", "correct": false}, {"id": "b", "text": "increases.", "correct": true}, {"id": "c", "text": "is zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If in a electrical circuit there is a difference between the capacitive reactance and the inductive reactance, what would the power factor of the circuit be?', '[{"id": "a", "text": "More than unity.", "correct": false}, {"id": "b", "text": "Less than unity.", "correct": true}, {"id": "c", "text": "Unity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a Series LC circuit if the value of the capacitance is increased then the power factor will be', '[{"id": "a", "text": "greater than 1.", "correct": false}, {"id": "b", "text": "less than 1.", "correct": true}, {"id": "c", "text": "equal to 1.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the current in the circuit with a resistance of 8 ohms, inductive reactance of 12 ohms, capacitive reactance of 18 ohms with 20 volts applied across it?', '[{"id": "a", "text": "10 amps.", "correct": false}, {"id": "b", "text": "1 amp.", "correct": false}, {"id": "c", "text": "2 amps.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A circuit containing a resistor, capacitor and inductor where resonant frequency is met, what will the impedance of the circuit be?', '[{"id": "a", "text": "Maximum.", "correct": false}, {"id": "b", "text": "Resistance across the resistor.", "correct": true}, {"id": "c", "text": "Zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'How many turns does the secondary winding of a 2:1 step-up transformer have?', '[{"id": "a", "text": "Less than primary.", "correct": false}, {"id": "b", "text": "More than primary.", "correct": true}, {"id": "c", "text": "Less turns but with thicker wire.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To reduce eddy currents in a transformer you would', '[{"id": "a", "text": "increase the thickness of laminations in the magnetic core.", "correct": false}, {"id": "b", "text": "reduce the number of turns on the primary winding.", "correct": false}, {"id": "c", "text": "reduce the thickness of laminations in the magnetic core.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer has an input of 400 V and a ratio of 2:1. If the transformer is delta / star wound, what will the line voltage output be?', '[{"id": "a", "text": "115V.", "correct": false}, {"id": "b", "text": "346V.", "correct": true}, {"id": "c", "text": "200V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A Transformer with 115 V primary voltage and a ratio of 5:1 is supplying a landing light (load 24 V 45 amps) is used, what is the current drawn?', '[{"id": "a", "text": "205 amps.", "correct": false}, {"id": "b", "text": "5 amps.", "correct": false}, {"id": "c", "text": "9 amps.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A Transformer has 4500 secondary turns and 750 primary turns. Its turns ratio is', '[{"id": "a", "text": "6:1.", "correct": false}, {"id": "b", "text": "1/6.", "correct": false}, {"id": "c", "text": "1:6.", "correct": true}]'::jsonb, '{B1,B2}'),
