    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The primary winding of a 3-phase transformer', '[{"id": "a", "text": "is delta wound.", "correct": false}, {"id": "b", "text": "could be either delta or star wound.", "correct": true}, {"id": "c", "text": "is star wound.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a transformer, if the rate of change of current increases, the mutual inductance will', '[{"id": "a", "text": "decrease.", "correct": false}, {"id": "b", "text": "remain the same.", "correct": true}, {"id": "c", "text": "increase.", "correct": false}]'::jsonb, '{B1,B2}'),
