    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A step up transformer has', '[{"id": "a", "text": "two windings.", "correct": true}, {"id": "b", "text": "one winding.", "correct": false}, {"id": "c", "text": "three windings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a transformer core loss is 200 W and copper loss is 220 W at no load. What is the core loss at full load?', '[{"id": "a", "text": "200 W.", "correct": true}, {"id": "b", "text": "0 W.", "correct": false}, {"id": "c", "text": "220 W.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The secondary winding of a transformer has an impedance of 10 ohms and 1500 turns. For the primary winding to have an impedance of 1 kilohm, how many turns must it have?', '[{"id": "a", "text": "15,000.", "correct": true}, {"id": "b", "text": "1,500,000.", "correct": false}, {"id": "c", "text": "150,000", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Eddy currents in a transformer core are reduced by', '[{"id": "a", "text": "decreasing the thickness of the laminates.", "correct": true}, {"id": "b", "text": "making the core from a solid block.", "correct": false}, {"id": "c", "text": "increasing the thickness of the laminates.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Transformer copper loss on full load is 220 Watts. On half load the loss will be', '[{"id": "a", "text": "440 Watts.", "correct": false}, {"id": "b", "text": "110 Watts.", "correct": false}, {"id": "c", "text": "55 Watts.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'How can it be determined if a transformer winding has some of its turns shorted together?', '[{"id": "a", "text": "Measure the input voltage with an ohmmeter.", "correct": false}, {"id": "b", "text": "The output voltage will be high.", "correct": false}, {"id": "c", "text": "The transformer will get hot in normal operation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Eddy currents in a transformer can be reduced by', '[{"id": "a", "text": "using a single solid piece of metal.", "correct": false}, {"id": "b", "text": "laminations.", "correct": true}, {"id": "c", "text": "using a special non metallic material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the ratio of turns between the primary coil winding and the secondary coil winding of a transformer designed to triple its input voltage?', '[{"id": "a", "text": "primary will have one-third as many turns as its secondary.", "correct": true}, {"id": "b", "text": "primary will have three times as many turns as its secondary.", "correct": false}, {"id": "c", "text": "primary will have twice as many turns as its secondary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer should always have its', '[{"id": "a", "text": "primary shorted or off load.", "correct": false}, {"id": "b", "text": "secondary shorted or on load.", "correct": true}, {"id": "c", "text": "secondary open circuit or on load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which of the following would be used to calculate transformer turns ratio?', '[{"id": "a", "text": "Secondary turns ÷ primary turns.", "correct": false}, {"id": "b", "text": "Primary turns × secondary turns.", "correct": false}, {"id": "c", "text": "Primary turns ÷ secondary turns.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The area of a hysteresis loop is proportional to the', '[{"id": "a", "text": "energy dissipated in putting the material through a complete cycle of magnetization and", "correct": false}, {"id": "b", "text": "demagnetization.", "correct": true}, {"id": "c", "text": "relative permeability of the material being magnetized.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In transformer operation, hysteresis losses are', '[{"id": "a", "text": "current overcoming coil resistance.", "correct": false}, {"id": "b", "text": "induced current in the iron core.", "correct": false}, {"id": "c", "text": "energy wasted in reversing core magnetization.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What causes a transformer to be noisy?', '[{"id": "a", "text": "High core losses.", "correct": false}, {"id": "b", "text": "An air gap in the core.", "correct": true}, {"id": "c", "text": "High coil resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer with a 5:1 ratio has a 24 V output. What is the input?', '[{"id": "a", "text": "120 V DC.", "correct": false}, {"id": "b", "text": "8 V AC.", "correct": false}, {"id": "c", "text": "120 V AC.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Copper losses in a transformer are caused by', '[{"id": "a", "text": "the resistance in the windings.", "correct": true}, {"id": "b", "text": "wasting of the copper wires due to friction.", "correct": false}, {"id": "c", "text": "circulating currents through the transformer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The copper loss on a single phase transformer is 25 Watts on full load. What will it be on half load?', '[{"id": "a", "text": "12.5 Watts.", "correct": false}, {"id": "b", "text": "6.25 Watts.", "correct": true}, {"id": "c", "text": "5 Watts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer is designed to operate at 60 Hz. It is connected across a 50 Hz supply. The primary windings would', '[{"id": "a", "text": "draw more current.", "correct": true}, {"id": "b", "text": "draw the same current.", "correct": false}, {"id": "c", "text": "draw less current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A current transformer, when disconnected from a circuit must be', '[{"id": "a", "text": "left open circuit.", "correct": false}, {"id": "b", "text": "short circuited.", "correct": true}, {"id": "c", "text": "have a resistor connected across the terminals.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer rated at a frequency of 200 Hz', '[{"id": "a", "text": "may be used at any other frequency.", "correct": false}, {"id": "b", "text": "may only be used at the rated frequency or above.", "correct": true}, {"id": "c", "text": "may only be used at the rated frequency or below.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer is built with a material having a', '[{"id": "a", "text": "high coercive force.", "correct": false}, {"id": "b", "text": "wide hysteresis loop.", "correct": false}, {"id": "c", "text": "narrow hysteresis loop.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer has 500 turns on the primary and 100 turns on the secondary. When connected to a 100 V supply, the output is', '[{"id": "a", "text": "500 V.", "correct": false}, {"id": "b", "text": "25 V.", "correct": false}, {"id": "c", "text": "20 V.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer has 500 turns on the primary and 100 turns on the secondary. The secondary supplies 20 V and is connected to a 10 ohm load. The primary current is', '[{"id": "a", "text": "2 amps.", "correct": false}, {"id": "b", "text": "0.4 amps.", "correct": true}, {"id": "c", "text": "10 amps.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer has 1200 turns primary and 4800 turns secondary. What value of load resistance would be required to give a reflected impedance of 1000 ohms?', '[{"id": "a", "text": "4 kOhm.", "correct": false}, {"id": "b", "text": "1 kOhm.", "correct": false}, {"id": "c", "text": "16 kOhm.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An autotransformer windings are', '[{"id": "a", "text": "wired in parallel.", "correct": false}, {"id": "b", "text": "on separate formers.", "correct": false}, {"id": "c", "text": "connected.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What voltage can the neutral line carry in a star transformer?', '[{"id": "a", "text": "Zero voltage.", "correct": true}, {"id": "b", "text": "Phase voltage.", "correct": false}, {"id": "c", "text": "Combined line voltages.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer to supply a 24 V load with a 5:1 turns ratio will have what primary supply?', '[{"id": "a", "text": "120 V AC.", "correct": true}, {"id": "b", "text": "48 V AC.", "correct": false}, {"id": "c", "text": "120 V DC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A transformer has 2000V, 500 turns on the primary and 50 turns on the secondary. What would be the line voltage if the transformer were Delta/Star connected?', '[{"id": "a", "text": "200V.", "correct": false}, {"id": "b", "text": "450V.", "correct": false}, {"id": "c", "text": "346V.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The line voltage in a Wye wound transformer is', '[{"id": "a", "text": "root 3 / phase voltage.", "correct": false}, {"id": "b", "text": "root 3 * phase voltage.", "correct": true}, {"id": "c", "text": "the same as phase voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Eddy current losses in a transformer are', '[{"id": "a", "text": "magnetic flows induced into the core.", "correct": true}, {"id": "b", "text": "current used in magnetising the core.", "correct": false}, {"id": "c", "text": "hysteresis losses.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 3-phase star-delta wound transformer gives', '[{"id": "a", "text": "30° phase shift.", "correct": true}, {"id": "b", "text": "90° phase shift.", "correct": false}, {"id": "c", "text": "no phase shift.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a 4:1 step up transformer, what would give a reflected impedance of 1 kOhm?', '[{"id": "a", "text": "1 kOhm.", "correct": false}, {"id": "b", "text": "16 kOhm.", "correct": true}, {"id": "c", "text": "4 kOhm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A near perfect 4:1 step up transformer has it’s primary connected to 120VAC, if the secondary is connected to a load with 1600 ohms resistance, what is the current in the primary?', '[{"id": "a", "text": "0.3 amps.", "correct": false}, {"id": "b", "text": "1 amp.", "correct": false}, {"id": "c", "text": "1.2 amps.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Flux losses in a transformer can be prevented by', '[{"id": "a", "text": "winding the primary on top of the secondary.", "correct": true}, {"id": "b", "text": "the use of primary shielding.", "correct": false}, {"id": "c", "text": "laminating the core.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To supply a 24volt output with a transformer with a 5:1 turns ratio, the input required is', '[{"id": "a", "text": "4.8", "correct": false}, {"id": "b", "text": "24V.", "correct": false}, {"id": "c", "text": "120V.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What would you use for the core in a generator current transformer?', '[{"id": "a", "text": "Air core.", "correct": false}, {"id": "b", "text": "Laminated core.", "correct": true}, {"id": "c", "text": "Steel Core.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An aircraft transformer is needed to step up a voltage. What sort would be used?', '[{"id": "a", "text": "Air core.", "correct": false}, {"id": "b", "text": "Solid core.", "correct": false}, {"id": "c", "text": "Laminated core.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a 4:1 step-up transformer, 120 V is applied to the primary, and the load on the secondary is 1600 Ohms. What is the current in the primary?', '[{"id": "a", "text": "0.075A", "correct": false}, {"id": "b", "text": "1.2A", "correct": true}, {"id": "c", "text": "3A", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A 10:1 step up power transformer has 120 V, and 3 A flowing through the primary, and 0.285 A flowing through the secondary what is the efficiency?', '[{"id": "a", "text": "90%.", "correct": false}, {"id": "b", "text": "95%.", "correct": true}, {"id": "c", "text": "85%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Aircraft autotransformers are of what type?', '[{"id": "a", "text": "Open core.", "correct": false}, {"id": "b", "text": "Twin core.", "correct": false}, {"id": "c", "text": "Laminated core.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An autotransformer is', '[{"id": "a", "text": "primary and secondary coils.", "correct": false}, {"id": "b", "text": "primary coil only.", "correct": false}, {"id": "c", "text": "primary and secondary coils on single bar.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which is a high-pass filter?', '[{"id": "a", "text": "L type with series L and shunt C.", "correct": false}, {"id": "b", "text": "L type with series C and shunt L.", "correct": true}, {"id": "c", "text": "π type with series C and L.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A high pass filter will', '[{"id": "a", "text": "allow frequencies above a certain value to pass.", "correct": true}, {"id": "b", "text": "allow frequencies within a range to pass.", "correct": false}, {"id": "c", "text": "allow frequencies below a certain value to pass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A band stop filter', '[{"id": "a", "text": "attenuates frequencies either side of a narrow range.", "correct": false}, {"id": "b", "text": "stops a narrow range of frequencies.", "correct": true}, {"id": "c", "text": "stops frequencies either side of a narrow range.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A capacitor in series and inductor in parallel make what kind of filter?', '[{"id": "a", "text": "Low pass.", "correct": false}, {"id": "b", "text": "Band pass.", "correct": false}, {"id": "c", "text": "High pass.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A high pass filter has', '[{"id": "a", "text": "high impedance to high frequency, low impedance to low frequency.", "correct": false}, {"id": "b", "text": "high impedance to both high and low frequency.", "correct": false}, {"id": "c", "text": "high impedance to low frequency, low impedance to high frequency.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A circuit with good selectivity will have', '[{"id": "a", "text": "a large bandwidth.", "correct": false}, {"id": "b", "text": "a narrow bandwidth.", "correct": true}, {"id": "c", "text": "a low L/C ratio.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A filter with a small bandwidth has', '[{"id": "a", "text": "a high value of Q.", "correct": true}, {"id": "b", "text": "a Q of zero.", "correct": false}, {"id": "c", "text": "a low value of Q.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Band stop filter', '[{"id": "a", "text": "attenuates frequencies in a specified narrow band.", "correct": true}, {"id": "b", "text": "stops frequencies in a narrow band.", "correct": false}, {"id": "c", "text": "pass all frequencies in that band.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Band pass filter in a circuit', '[{"id": "a", "text": "only allows a narrow band of frequency to pass.", "correct": true}, {"id": "b", "text": "allows frequencies below a cut-off frequency to pass.", "correct": false}, {"id": "c", "text": "allows frequencies above a cut-off frequency to pass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A high pass filter consists of a', '[{"id": "a", "text": "capacitor in series and inductor in series.", "correct": false}, {"id": "b", "text": "capacitor in series and inductor in parallel.", "correct": true}, {"id": "c", "text": "an inductor in series and a capacitor in parallel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In an alternating current Star wired system, the phase voltage is 115 volts and the line voltage will be approximately', '[{"id": "a", "text": "200 volts.", "correct": true}, {"id": "b", "text": "115 volts.", "correct": false}, {"id": "c", "text": "163 volts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An alternating current generator is operating at 50 kVA in a circuit with a power factor of 0.8. The real power is', '[{"id": "a", "text": "40kW.", "correct": true}, {"id": "b", "text": "72kW.", "correct": false}, {"id": "c", "text": "50kW.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The two factors which govern the output frequency of an AC generator are the', '[{"id": "a", "text": "the number of poles (in pairs) and the rotor RPM.", "correct": true}, {"id": "b", "text": "strength of the stator field flux and number of poles.", "correct": false}, {"id": "c", "text": "speed of rotation of the rotor and the stator field flux strength.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a delta-connected generator', '[{"id": "a", "text": "line voltage = root 3 times phase voltage, line current = phase current.", "correct": false}, {"id": "b", "text": "line volts = phase volts, line current = phase current divided by root 3.", "correct": false}, {"id": "c", "text": "line volts = phase volts, line current = root 3 times phase current.", "correct": true}]'::jsonb, '{B1,B2}'),
