    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The permanent magnet in an A.C generator induces', '[{"id": "a", "text": "A.C. in the main generator.", "correct": false}, {"id": "b", "text": "A.C. in the exciter generator.", "correct": true}, {"id": "c", "text": "D.C. in the exciter generator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the phase voltage in a star connected generator is 200 V what will be the line voltage?', '[{"id": "a", "text": "115V.", "correct": false}, {"id": "b", "text": "346V.", "correct": true}, {"id": "c", "text": "200V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A generator is labeled as having 115V/200V, 20 A and PF 0.8. What is the apparent power in each line that the generator can produce?', '[{"id": "a", "text": "3kVA.", "correct": false}, {"id": "b", "text": "3kW.", "correct": false}, {"id": "c", "text": "4kVA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'AC generators are rated in', '[{"id": "a", "text": "kVA.", "correct": true}, {"id": "b", "text": "kVARs.", "correct": false}, {"id": "c", "text": "kW.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The frequency of the output of a 4 pole generator is 400 Hz. The generator is turning at', '[{"id": "a", "text": "6000 RPM.", "correct": false}, {"id": "b", "text": "12000 RPM.", "correct": true}, {"id": "c", "text": "3000 RPM.", "correct": false}]'::jsonb, '{B1,B2}'),
