    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The three voltages of a three phase generator are connected', '[{"id": "a", "text": "in series with each other.", "correct": true}, {"id": "b", "text": "independently of each other.", "correct": false}, {"id": "c", "text": "in parallel with each other.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a 2 phase generator, how far apart are the windings electrically?', '[{"id": "a", "text": "45°.", "correct": false}, {"id": "b", "text": "180°.", "correct": false}, {"id": "c", "text": "90°.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Where are the output windings on an AC generator?', '[{"id": "a", "text": "Rotor with slip rings.", "correct": false}, {"id": "b", "text": "Rotor with commutator.", "correct": false}, {"id": "c", "text": "Stator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The line voltage from a generator with a delta type connection will be', '[{"id": "a", "text": "lower than the phase voltage.", "correct": false}, {"id": "b", "text": "higher than the phase voltage.", "correct": false}, {"id": "c", "text": "the same as the phase voltage.", "correct": true}]'::jsonb, '{B1,B2}'),
