    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A frequency wild AC generator is used for', '[{"id": "a", "text": "any AC load.", "correct": false}, {"id": "b", "text": "deicing loads.", "correct": true}, {"id": "c", "text": "instruments and navigation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'How many cycles of AC voltage are produced in a six-pole alternator of the revolving-field type, with each revolution of the rotor?', '[{"id": "a", "text": "Six.", "correct": false}, {"id": "b", "text": "Four.", "correct": false}, {"id": "c", "text": "Three.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The variable frequency output from an AC generator is used for', '[{"id": "a", "text": "driving AC operated instruments.", "correct": false}, {"id": "b", "text": "supplying non-inductive loads.", "correct": true}, {"id": "c", "text": "the AC supply instead of using inverters.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The amount of electrical power for a given generator weight is', '[{"id": "a", "text": "greater for AC generator.", "correct": true}, {"id": "b", "text": "determined by the size of the aircraft.", "correct": false}, {"id": "c", "text": "greater for DC generator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'On a typical AC generator the output is taken', '[{"id": "a", "text": "direct from the rotor via slip rings.", "correct": false}, {"id": "b", "text": "direct from the stator windings.", "correct": true}, {"id": "c", "text": "direct from the exciter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An AC generator is producing the required voltage but a higher frequency than that required. To remedy this, the following action must be taken?', '[{"id": "a", "text": "Decrease the speed of the prime mover.", "correct": false}, {"id": "b", "text": "Decrease the speed of the prime mover, and then decrease the strength of the field.", "correct": false}, {"id": "c", "text": "Decrease the speed of the prime mover, and then increase the strength of the field.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a 3 phase generator with balanced load, the potential between the neutral point and earth is', '[{"id": "a", "text": "equal to line volts.", "correct": false}, {"id": "b", "text": "zero volts.", "correct": true}, {"id": "c", "text": "equal to phase volts.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The power output of an AC parallel generator system is measured in', '[{"id": "a", "text": "KW / KVARS.", "correct": true}, {"id": "b", "text": "amperes.", "correct": false}, {"id": "c", "text": "KVA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The shape of the output waveform of an AC generator is known as a', '[{"id": "a", "text": "sine wave.", "correct": true}, {"id": "b", "text": "frequency wave.", "correct": false}, {"id": "c", "text": "cosine wave.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The sum of the instantaneous E.M.F.’s in a three phase system is', '[{"id": "a", "text": "three times the phase voltage.", "correct": false}, {"id": "b", "text": "zero.", "correct": true}, {"id": "c", "text": "equal to the line voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'One revolution of a three phase generator will produce', '[{"id": "a", "text": "1 cycle.", "correct": false}, {"id": "b", "text": "3 cycles.", "correct": true}, {"id": "c", "text": "2 cycles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The ’A’ phase of a three phase power system is colour coded', '[{"id": "a", "text": "red.", "correct": true}, {"id": "b", "text": "blue.", "correct": false}, {"id": "c", "text": "yellow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The tolerance of the AC generator frequency is', '[{"id": "a", "text": "10 Hz.", "correct": false}, {"id": "b", "text": "40 Hz.", "correct": false}, {"id": "c", "text": "20 Hz.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A generator supplies 25 A, 4 V and 50 W. What is the apparent power and the power factor?', '[{"id": "a", "text": "400 VA and 0.5.", "correct": false}, {"id": "b", "text": "100 VA and 2.", "correct": false}, {"id": "c", "text": "100 VA and 0.5.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A conventional aircraft generator will be', '[{"id": "a", "text": "delta wound.", "correct": false}, {"id": "b", "text": "series wound.", "correct": false}, {"id": "c", "text": "star wound.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Power factor of a generator is', '[{"id": "a", "text": "tan φ.", "correct": false}, {"id": "b", "text": "cos φ.", "correct": true}, {"id": "c", "text": "sin φ.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a 3 phase generator, what angle are the phases to each other?', '[{"id": "a", "text": "180°.", "correct": false}, {"id": "b", "text": "120°.", "correct": true}, {"id": "c", "text": "0°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a 2 phase generator, what angle are the phases to each other?', '[{"id": "a", "text": "90°.", "correct": true}, {"id": "b", "text": "0°.", "correct": false}, {"id": "c", "text": "180°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Delta wound line current is', '[{"id": "a", "text": "equal to phase current.", "correct": false}, {"id": "b", "text": "root 3 * phase current.", "correct": true}, {"id": "c", "text": "less than the phase current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An alternator delivers 500 V RMS at 1 ampere. The power factor is 0.8. The true power is', '[{"id": "a", "text": "500W.", "correct": false}, {"id": "b", "text": "100VA.", "correct": false}, {"id": "c", "text": "400W.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'On a brushless AC generator, the main rotating field is fed with', '[{"id": "a", "text": "DC via diodes on the rotor.", "correct": true}, {"id": "b", "text": "AC.", "correct": false}, {"id": "c", "text": "AC from the rotating field exciter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Single phase components in a three phase system may be connected between', '[{"id": "a", "text": "phase A and B only.", "correct": false}, {"id": "b", "text": "any phase and neutral OR between any two phases.", "correct": true}, {"id": "c", "text": "phase and neutral only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A generator rated at 30 KVA and power factor 0.8 has a maximum continuous power output of', '[{"id": "a", "text": "30 kW.", "correct": false}, {"id": "b", "text": "24 kW.", "correct": true}, {"id": "c", "text": "48 kW.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If there was a mainly inductive load on an AC generator, the voltage with respect to the current would', '[{"id": "a", "text": "lag.", "correct": false}, {"id": "b", "text": "be in phase.", "correct": false}, {"id": "c", "text": "lead.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'On a brushless AC generator, the permanent magnet generator output is', '[{"id": "a", "text": "DC.", "correct": false}, {"id": "b", "text": "pulsed.", "correct": false}, {"id": "c", "text": "AC.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The output from a rotating armature AC generator would be taken from', '[{"id": "a", "text": "either the rotor or the stator.", "correct": false}, {"id": "b", "text": "the rotor.", "correct": true}, {"id": "c", "text": "the stator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A frequency wild AC generator system has', '[{"id": "a", "text": "variable voltage only.", "correct": false}, {"id": "b", "text": "variable voltage and frequency.", "correct": true}, {"id": "c", "text": "variable frequency only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An AC generator has four poles. To produce a frequency of 400 Hz it must achieve a speed of', '[{"id": "a", "text": "6000 RPM.", "correct": false}, {"id": "b", "text": "3000 RPM.", "correct": false}, {"id": "c", "text": "12000 RPM.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The stator of a permanent magnet rotor AC generator', '[{"id": "a", "text": "is usually star wound.", "correct": true}, {"id": "b", "text": "is wound in series with the field.", "correct": false}, {"id": "c", "text": "is usually delta wound.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The power output of a similar sized 3 phase compared to a single phase generator is', '[{"id": "a", "text": "more.", "correct": true}, {"id": "b", "text": "same.", "correct": false}, {"id": "c", "text": "less.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a voltage equalising circuit the generators are regulated so', '[{"id": "a", "text": "the higher output is decreased to that of the lower.", "correct": false}, {"id": "b", "text": "the lower is increased and the higher is decreased until they are equal.", "correct": true}, {"id": "c", "text": "the lower output is increased to that of the higher.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a 3-phase delta wound circuit, line current is', '[{"id": "a", "text": "same as the phase current.", "correct": false}, {"id": "b", "text": "the vectorial sum of all 3 phase currents.", "correct": true}, {"id": "c", "text": "in phase with the phase current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In an aircraft brushless alternator the armature is', '[{"id": "a", "text": "in series with the field.", "correct": false}, {"id": "b", "text": "delta wound.", "correct": false}, {"id": "c", "text": "star wound.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the phase voltage of a star wound generator is 115V, what would be the line to line voltage?', '[{"id": "a", "text": "220V.", "correct": false}, {"id": "b", "text": "180V.", "correct": false}, {"id": "c", "text": "200V.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What are the factors affecting the frequency of an AC generator?', '[{"id": "a", "text": "Number of pole pairs and rpm.", "correct": true}, {"id": "b", "text": "Number of turns in the armature coil and number of pole pairs.", "correct": false}, {"id": "c", "text": "Number of turns in the armature coil and rpm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A generator with more than two phases is known as', '[{"id": "a", "text": "polyphase.", "correct": true}, {"id": "b", "text": "multiphase.", "correct": false}, {"id": "c", "text": "delta phase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A generator supplies 150VAC phase and load is 10 Ohms per phase. What is the phase current ?', '[{"id": "a", "text": "25.5 A.", "correct": false}, {"id": "b", "text": "1.5 A.", "correct": false}, {"id": "c", "text": "15 A.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The phases on a three phase AC generator are spaced at', '[{"id": "a", "text": "120 degrees.", "correct": true}, {"id": "b", "text": "90 degrees.", "correct": false}, {"id": "c", "text": "180 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Increasing the load on a permanent magnet generator will', '[{"id": "a", "text": "reduce the terminal voltage by a large amount.", "correct": true}, {"id": "b", "text": "reduce the terminal voltage by a small amount.", "correct": false}, {"id": "c", "text": "increase the terminal voltage by a small amount.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Two 3 phase generators operating in parallel with different phase and line voltages will be connected in', '[{"id": "a", "text": "Parallel configuration.", "correct": false}, {"id": "b", "text": "star configuration.", "correct": true}, {"id": "c", "text": "delta configuration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The Stability windings in a 3 phase AC generator are to sense', '[{"id": "a", "text": "field oscillations.", "correct": true}, {"id": "b", "text": "overvolt.", "correct": false}, {"id": "c", "text": "phase shift.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Delta wound alternator currents are', '[{"id": "a", "text": "the same as line current.", "correct": false}, {"id": "b", "text": "the same as phase current.", "correct": false}, {"id": "c", "text": "the phase current multiplied be the square root of 3.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In smaller single or twin engine aircraft the primary DC power is supplied in the form of rectified output from', '[{"id": "a", "text": "constant frequency ac generator.", "correct": false}, {"id": "b", "text": "inverter.", "correct": false}, {"id": "c", "text": "frequency wild ac generator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Single phase components in a 3 phase system may be connected between', '[{"id": "a", "text": "any phase and earth or between any two phases.", "correct": true}, {"id": "b", "text": "any phase and earth.", "correct": false}, {"id": "c", "text": "phase A and B only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Under frequency in an AC supply would cause', '[{"id": "a", "text": "overheating of inductive devices.", "correct": true}, {"id": "b", "text": "overspeeding of AC motors.", "correct": false}, {"id": "c", "text": "overvoltage of capacitive devices.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The line voltage of a 3 phase star connected AC generator is', '[{"id": "a", "text": "equal to the phase voltage.", "correct": false}, {"id": "b", "text": "greater than the phase voltage.", "correct": true}, {"id": "c", "text": "less than the phase voltage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In an AC generator of the brushless type the rotating field winding is fed with', '[{"id": "a", "text": "AC via rotating exciter windings.", "correct": false}, {"id": "b", "text": "DC via the slip rings from an external supply.", "correct": false}, {"id": "c", "text": "DC via diodes from the main exciter winding on the rotor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An AC generator is rated at 30 kVA at 0.8 Power Factor: this means that the maximum continuous output should not exceed', '[{"id": "a", "text": "24 KW.", "correct": true}, {"id": "b", "text": "30 KW.", "correct": false}, {"id": "c", "text": "5 KW.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To adjust the voltage of an AC generator, whilst maintaining constant frequency, it is necessary to', '[{"id": "a", "text": "alter the reactance of the starter winding circuit.", "correct": false}, {"id": "b", "text": "alter the field current.", "correct": true}, {"id": "c", "text": "alter the driving speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a Delta connected generator the line current is equal to', '[{"id": "a", "text": "1.7 * phase current.", "correct": true}, {"id": "b", "text": "1.7 * phase voltage.", "correct": false}, {"id": "c", "text": "phase current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An AC motor which rotates at the same speed as supply frequency is called', '[{"id": "a", "text": "a universal machine.", "correct": false}, {"id": "b", "text": "a synchronous motor.", "correct": true}, {"id": "c", "text": "an induction motor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A three phase AC motor is running at speed on constant load. If one phase goes open circuit, the motor will run at', '[{"id": "a", "text": "same speed.", "correct": true}, {"id": "b", "text": "⅓ speed.", "correct": false}, {"id": "c", "text": "⅔ speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Shaded poles in an alternating current motor are intended to', '[{"id": "a", "text": "reduce eddy current losses.", "correct": false}, {"id": "b", "text": "prevent overshooting.", "correct": false}, {"id": "c", "text": "facilitate starting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a 3 phase motor, if 1 phase is lost, the motor', '[{"id": "a", "text": "runs at 2 thirds speed.", "correct": false}, {"id": "b", "text": "runs at 1 third speed.", "correct": false}, {"id": "c", "text": "remains at the same speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A three-phase motor has the windings', '[{"id": "a", "text": "180° apart.", "correct": false}, {"id": "b", "text": "120° apart.", "correct": true}, {"id": "c", "text": "90° apart.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'To change the direction of a 3-phase induction motor you would', '[{"id": "a", "text": "swap all of the input connections.", "correct": false}, {"id": "b", "text": "remove one of the input connections.", "correct": false}, {"id": "c", "text": "swap two of the stator connections.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A capacitor in a single phase AC motor is to', '[{"id": "a", "text": "provide a phase shift.", "correct": true}, {"id": "b", "text": "prevent spikes.", "correct": false}, {"id": "c", "text": "block DC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The slip speed of an induction motor is', '[{"id": "a", "text": "stator speed-rotor speed.", "correct": true}, {"id": "b", "text": "stator speed / rotor speed.", "correct": false}, {"id": "c", "text": "stator speed + rotor speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An inductance/resistance motor is', '[{"id": "a", "text": "restricted to low loads only.", "correct": false}, {"id": "b", "text": "less efficient than a capacitance motor.", "correct": true}, {"id": "c", "text": "better than a capacitance motor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If in a 3-phase AC motor one phase is disconnected, the motor will', '[{"id": "a", "text": "continue to run.", "correct": true}, {"id": "b", "text": "slow down and stop.", "correct": false}, {"id": "c", "text": "stop.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Calculate the speed of a 400 Hz, 4 pole machine', '[{"id": "a", "text": "12,000 rpm.", "correct": true}, {"id": "b", "text": "6000 rpm.", "correct": false}, {"id": "c", "text": "8000 rpm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A capacitor in a single phase motor is to', '[{"id": "a", "text": "prevent sparking at the switch.", "correct": false}, {"id": "b", "text": "provide smoothing.", "correct": false}, {"id": "c", "text": "provide a phase shift.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Slip on a synchronous motor on start is', '[{"id": "a", "text": "0 %.", "correct": false}, {"id": "b", "text": "100 %.", "correct": true}, {"id": "c", "text": "50 %.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A shaded pole motor has shaded poles to', '[{"id": "a", "text": "create a rotating field.", "correct": true}, {"id": "b", "text": "reduce interference.", "correct": false}, {"id": "c", "text": "increase efficiency.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The speed of an AC motor can be affected by the', '[{"id": "a", "text": "field current.", "correct": false}, {"id": "b", "text": "armature current.", "correct": false}, {"id": "c", "text": "pairs of poles.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'An AC motor which rotates at the same speed as the supply frequency is called', '[{"id": "a", "text": "a synchronous motor.", "correct": true}, {"id": "b", "text": "a universal motor.", "correct": false}, {"id": "c", "text": "an induction motor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a synchronous motor, when the motor is running the slip is', '[{"id": "a", "text": "0%.", "correct": true}, {"id": "b", "text": "5%.", "correct": false}, {"id": "c", "text": "100%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'In a two-phase induction motor there are', '[{"id": "a", "text": "3 poles.", "correct": false}, {"id": "b", "text": "4 poles.", "correct": true}, {"id": "c", "text": "2 poles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The speed of a single phase induction motor is dependant on', '[{"id": "a", "text": "the strength of the armature current.", "correct": false}, {"id": "b", "text": "the number of pairs of poles.", "correct": true}, {"id": "c", "text": "the strength of the field.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Motor slip is', '[{"id": "a", "text": "the percentage of difference in speeds between the stator and rotor fields.", "correct": true}, {"id": "b", "text": "a symptom of a weak field.", "correct": false}, {"id": "c", "text": "a shifting of the MNA of the motor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The principal characteristic of a synchronous motor is', '[{"id": "a", "text": "it must have a synchronised 3 phase supply to operate.", "correct": false}, {"id": "b", "text": "it rotates at a speed that is synchronised with the applied dc current.", "correct": false}, {"id": "c", "text": "it rotates at a speed that is synchronised with the applied ac current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A simple basic induction motor has', '[{"id": "a", "text": "good starting torque, poor running torque.", "correct": false}, {"id": "b", "text": "poor starting torque, good running torque.", "correct": true}, {"id": "c", "text": "poor starting torque, poor running torque.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Which of the following applications would require a ’continuously rated’ motor?', '[{"id": "a", "text": "Fuel pump motor.", "correct": true}, {"id": "b", "text": "Flap drive actuator.", "correct": false}, {"id": "c", "text": "Cargo door actuator.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A centrifugal speed switch is used', '[{"id": "a", "text": "to cut out the resistor/inductor circuit on an AC motor.", "correct": false}, {"id": "b", "text": "to cut out the capacitor circuit on an AC motor.", "correct": true}, {"id": "c", "text": "to cut out the slow start resistor on an AC motor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Disconnecting one of the phases from a 3-phase motor will cause the motor to', '[{"id": "a", "text": "run at the same speed.", "correct": true}, {"id": "b", "text": "run at 2/3 speed.", "correct": false}, {"id": "c", "text": "stop.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The controlling phase on a two phase motor is of a', '[{"id": "a", "text": "variable amplitude.", "correct": true}, {"id": "b", "text": "fixed amplitude.", "correct": false}, {"id": "c", "text": "direct current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The difference in speed between a synchronous motor’s rotor and stator is known as', '[{"id": "a", "text": "phase lag.", "correct": false}, {"id": "b", "text": "rotor lag.", "correct": false}, {"id": "c", "text": "slip speed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'What is the purpose of the capacitor used in a single phase AC motor?', '[{"id": "a", "text": "Smoothing.", "correct": false}, {"id": "b", "text": "Changing direction of motor.", "correct": false}, {"id": "c", "text": "Provides a high starting torque.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Three 5-microfarad capacitors are connected in parallel. What is there total capacitance?', '[{"id": "a", "text": "15 microfarad.", "correct": true}, {"id": "b", "text": "5 microfarad.", "correct": false}, {"id": "c", "text": "66 microfarad.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'When capacitors are joined in parallel, the total capacitance is', '[{"id": "a", "text": "less than the smallest of the individual capacitors.", "correct": false}, {"id": "b", "text": "equal to the sum of the individual capacitors.", "correct": true}, {"id": "c", "text": "dependant upon the voltage applied.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'If the distance between the two plates of a capacitor is reduced, what will be the effect?', '[{"id": "a", "text": "Capacitance increases.", "correct": true}, {"id": "b", "text": "Capacitance decreases.", "correct": false}, {"id": "c", "text": "Capacitance is unaffected.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The strength of the EMF generated by a DC generator is given the formula : E = EMF, B = flux density, l = length of conductors in the armature, V = velocity of conductors', '[{"id": "a", "text": "E = (B*l)/V.", "correct": false}, {"id": "b", "text": "E = B*l*V.", "correct": true}, {"id": "c", "text": "E = (l*V)/B.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The rotating part of a motor/generator is called', '[{"id": "a", "text": "commutator.", "correct": false}, {"id": "b", "text": "armature.", "correct": true}, {"id": "c", "text": "yoke.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'No EMF is induced in the loop of a generator when', '[{"id": "a", "text": "it is moving at right angles to the field.", "correct": false}, {"id": "b", "text": "it is moving parallel to the field.", "correct": true}, {"id": "c", "text": "the field is at a minimum.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The instantaneous value of the EMF induced in a rotating wire loop is', '[{"id": "a", "text": "directly proportional to the sine of the angle between the loop and the field.", "correct": true}, {"id": "b", "text": "indirectly proportional to the sine of the angle between the loop and the field.", "correct": false}, {"id": "c", "text": "directly proportional to the cosine of the angle between the loop and the field.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'One purpose of the commutator is to', '[{"id": "a", "text": "switch the direction of the current flow every half cycle.", "correct": true}, {"id": "b", "text": "switch the direction of current flow every cycle.", "correct": false}, {"id": "c", "text": "switch the direction of current flow every two cycles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'The power output of a DC generator is governed primarily by', '[{"id": "a", "text": "its speed of rotation.", "correct": false}, {"id": "b", "text": "its ability to dissipate heat.", "correct": true}, {"id": "c", "text": "its method of construction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'A DC machine has internal resistance due to', '[{"id": "a", "text": "armature windings, brushes and brushes to commutator contact.", "correct": true}, {"id": "b", "text": "armature windings, brushes and commutator inertia.", "correct": false}, {"id": "c", "text": "armature windings and brushes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Compensation windings are fitted to a generator in', '[{"id": "a", "text": "series with the field windings.", "correct": false}, {"id": "b", "text": "parallel with armature windings.", "correct": false}, {"id": "c", "text": "series with armature windings.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Armature reaction has the effect of', '[{"id": "a", "text": "reducing the output by displacing the geometrical neutral axis.", "correct": false}, {"id": "b", "text": "reducing the output by distorting the magnetic field.", "correct": true}, {"id": "c", "text": "reducing the output by increasing internal resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'Reactive sparking maybe overcome by', '[{"id": "a", "text": "decreasing the time constant of the armature by increasing its resistance.", "correct": true}, {"id": "b", "text": "increasing the time constant of the armature by decreasing its resistance.", "correct": false}, {"id": "c", "text": "increasing the time constant of the armature by increasing its resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M03.17'), 'For the diagram shown find the voltage at point B.', '[{"id": "a", "text": "7V", "correct": false}, {"id": "b", "text": "10V", "correct": true}, {"id": "c", "text": "26V", "correct": false}]'::jsonb, '{B1,B2}');
